INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C1','kor',2,1,'u8',1,'여러 가지 작품과 감상의 즐거움 — 시·이야기·인형극의 특징을 알고, 작품을 즐기며 떠오른 생각이나 느낌을 친구와 나누는 것이 감상임을 알기(느낌은 사람마다 다를 수 있음)',ARRAY['2국05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C2','kor',2,1,'u8',1,'작품 속 인물의 마음 상상하기 — 마음이 글에 직접 나오지 않아도 인물이 처한 상황·말·행동을 근거로 마음을 상상하고 그렇게 생각한 까닭을 말하기',ARRAY['2국05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C3','kor',2,1,'u8',3,'시를 여러 방법으로 낭송하기 — 시의 리듬과 분위기를 살려 소리 내어 읽고, 주고받기·몸짓 넣기·박자 넣기처럼 방법을 바꾸어 낭송하며 느낌이 달라짐을 즐기기',ARRAY['2국05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C4','kor',2,1,'u8',3,'시 속 행동과 흉내 내는 말로 마음 짐작하기 — 「반갑다」 같은 말이 없어도 시 속 인물의 행동과 흉내 내는 말(흔들흔들·살금살금·새근새근)에서 마음을 짐작하기',ARRAY['2국05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C5','kor',2,1,'u8',5,'이야기 속 인물의 마음과 그 변화 — 인물의 말과 행동에서 마음을 짐작하고, 일이 일어남에 따라 마음이 어떻게 바뀌는지와 무엇 때문에 바뀌었는지 알기',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C6','kor',2,1,'u8',5,'기억에 남는 장면과 까닭 표현하기 — 작품에서 기억에 남는 장면을 고르고 그 까닭과 비슷한 내 경험을 함께 글·그림·말로 표현하기',ARRAY['2국05-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C7','kor',2,1,'u8',7,'인형극의 특징과 인물의 마음 짐작하기 — 인형극(그림자·막대·손가락 인형극)은 인형의 말·움직임·목소리로 이야기를 보여 주며, 목소리의 크기·빠르기와 움직임에서 인물의 마음을 짐작할 수 있음을 알기',ARRAY['2국05-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C8','kor',2,1,'u8',7,'일이 일어난 차례 정리하기 — 장소가 바뀌는 곳을 기준으로 장소마다 일어난 일을 차례대로 정리하여 줄거리를 파악하기',ARRAY['2국05-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C9','kor',2,1,'u8',9,'인형극 속 인물의 말과 행동 찾으며 감상하기 — 「의좋은 형제」처럼 인형극을 보며 인물이 무엇을 왜 했는지 말과 행동을 찾고 인상 깊은 장면을 떠올리기',ARRAY['2국05-03']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C10','kor',2,1,'u8',9,'인물에게 편지 쓰기 — 작품 속 인물에게 하고 싶은 말과 그 까닭을 받는 인물·쓴 사람이 드러나게 솔직한 마음으로 편지에 담기',ARRAY['2국05-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C11','kor',2,1,'u8',9,'감상을 발표하고 견주어 듣기 — 감상을 또박또박 까닭과 함께 발표하고, 친구의 감상은 좋은 점을 찾으며 끝까지 듣고 내 감상과 비슷한 점·다른 점을 견주기',ARRAY['2국01-05']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C12','kor',2,1,'u8',12,'인형극 준비하고 공연·관람하기 — 보여 줄 장면과 역할을 정하고 막대 인형을 간단히 만들어(그리기→오리기→막대 붙이기) 인물의 마음을 살린 목소리·움직임으로 공연하며, 바른 자세로 관람하고 감상을 나누기',ARRAY['2국05-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C13','kor',2,1,'u8',14,'받침이 넘어가는 소리 — 받침 뒤에 「ㅇ」으로 시작하는 글자가 오면 받침이 뒤 글자의 첫소리로 넘어가 소리 남을 알고(구름이[구르미]) 자연스럽게 읽기',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X01','kor',2,'u8',ARRAY['K2-1-u8-C1','K2-1-u8-C7']::text[],'시·이야기·인형극의 특징을 헷갈리거나 작품을 감상한 경험이 아닌 일을 감상 경험으로 여긴다','「소리 내어 낭송? 겪은 일을 차례로? 인형이 나와 보여 줌?」 하나씩 맞춰 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X02','kor',2,'u8',ARRAY['K2-1-u8-C1','K2-1-u8-C3','K2-1-u8-C6','K2-1-u8-C8','K2-1-u8-C11']::text[],'감상에 정답이 하나뿐이라고 여기거나, 빨리 읽기·외우기·잘하기가 감상에서 가장 중요하다고 여긴다','「나는 어떤 느낌이었지?」 먼저 묻고 친구 느낌도 들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X03','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C6','K2-1-u8-C8','K2-1-u8-C9','K2-1-u8-C10','K2-1-u8-C11']::text[],'작품에 없는 내용을 있다고 하거나 작품 내용을 놓친다','작품에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X04','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C5','K2-1-u8-C6','K2-1-u8-C8','K2-1-u8-C9','K2-1-u8-C12']::text[],'인물을 뒤바꿔 다른 인물이 한 말·행동·마음을 말한다','누가 한 말·행동인지 이름에 동그라미 치고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X05','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C7','K2-1-u8-C9']::text[],'상황에 맞지 않게 인물의 마음을 짐작하거나, 마음이 글에 직접 쓰여 있지 않으면 짐작할 수 없다고 여긴다','내가 그 인물이라면 그때 어떤 마음일지 바꿔 생각해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X06','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C9']::text[],'마음을 짐작한 까닭이나 비슷한 경험으로 작품과 상관없는 것(옷 색깔·쪽수·마음이 드러나지 않는 부분)을 든다','「이 말·행동에 마음이 보이나?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X07','kor',2,'u8',ARRAY['K2-1-u8-C4']::text[],'흉내 내는 말의 뜻을 헷갈리거나 흉내 내는 말과 다른 낱말을 가리지 못한다','흉내 내는 말을 몸짓으로 따라 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X08','kor',2,'u8',ARRAY['K2-1-u8-C3']::text[],'낭송 방법(주고받기·몸짓·박자)을 헷갈리거나 시의 분위기와 맞지 않게 낭송한다','시가 조용한 시인지 신나는 시인지 먼저 정하고 목소리 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X09','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C5']::text[],'인물의 마음이 바뀌는 것을 놓치거나(처음 마음 = 끝 마음) 바뀐 차례를 거꾸로 짚는다','처음·가운데·끝 장면마다 마음을 따로 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X10','kor',2,'u8',ARRAY['K2-1-u8-C6','K2-1-u8-C11']::text[],'감상을 말할 때 장면만 말하고 까닭을 빠뜨리거나, 느낌 없이 줄거리만 옮긴다','「왜냐하면」을 붙여 한 번 더 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X11','kor',2,'u8',ARRAY['K2-1-u8-C7']::text[],'인형극의 특징(인형·움직임·목소리)과 종류(그림자·막대·손가락)를 헷갈린다','인형을 무엇으로 움직이는지 떠올려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X12','kor',2,'u8',ARRAY['K2-1-u8-C7','K2-1-u8-C12']::text[],'목소리의 크기·빠르기·움직임과 인물의 마음의 짝을 헷갈린다(떨리는 작은 목소리 → 신남)','그 목소리로 직접 말해 보고 어떤 마음인지 느껴 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X13','kor',2,'u8',ARRAY['K2-1-u8-C8']::text[],'일이 일어난 차례나 장소가 바뀐 차례를 뒤섞는다','장소가 바뀌는 곳에 줄을 긋고 번호 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X14','kor',2,'u8',ARRAY['K2-1-u8-C10']::text[],'인물에게 쓰는 편지에서 받는 인물·하고 싶은 말·까닭·쓴 사람을 빠뜨리거나 헷갈리고, 작품과 상관없는 사람에게 쓴다','누구에게 · 하고 싶은 말 · 왜 · 누가 — 네 가지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X15','kor',2,'u8',ARRAY['K2-1-u8-C11']::text[],'바르지 않은 발표·듣기 자세를 괜찮다고 여기거나, 나와 다른 친구의 감상을 틀렸다고 여긴다','친구 감상에서 좋은 점 하나 먼저 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X16','kor',2,'u8',ARRAY['K2-1-u8-C12']::text[],'인형극을 준비·공연할 때 인형 꾸미기에만 매달리거나 역할을 나누지 않고, 인물의 마음을 살리지 않고 대사를 읽는다','「인형보다 놀이!」 — 장면·역할·마음 담은 대사 먼저 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X17','kor',2,'u8',ARRAY['K2-1-u8-C12']::text[],'인형극을 볼 때의 약속(조용히 바른 자세로 보기·끝난 뒤 좋았던 점 나누기)을 지키지 않아도 된다고 여긴다','내가 무대에 섰다면 관객이 어떻게 해 주면 좋을지 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X18','kor',2,'u8',ARRAY['K2-1-u8-C13']::text[],'받침이 넘어가는 소리를 헷갈린다 — 「ㅇ」 앞에서도 받침을 그대로 읽거나, 「ㅇ」이 아닌 글자 앞에서도 받침을 넘겨 읽는다','받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X19','kor',2,'u8',ARRAY['K2-1-u8-C1','K2-1-u8-C2','K2-1-u8-C3','K2-1-u8-C4','K2-1-u8-C5','K2-1-u8-C6','K2-1-u8-C7','K2-1-u8-C8','K2-1-u8-C9','K2-1-u8-C10','K2-1-u8-C11','K2-1-u8-C12','K2-1-u8-C13']::text[],'묻는 말을 거꾸로 읽는다 — 알맞지 않은↔알맞은, 잘못↔바르게, 아닌↔맞는','물음의 「않은·잘못·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#1','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',1,'mc','auto','소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],true,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?","options":[{"t":"시","correct":true},{"t":"이야기","mis":"K2-1-u8-X01"},{"t":"인형극","mis":"K2-1-u8-X01"}],"explanation":["시는 짧은 말에 리듬을 담아 소리 내어 낭송하며 즐겨요.","이야기는 인물이 겪은 일을 차례대로 들려주는 작품이에요.","인형극은 인형이 나와 말과 행동으로 보여 주는 작품이에요."],"variant_rule":{"alt":[{"stem":"인형이 나와 말과 행동으로 이야기를 보여 주는 작품은 어느 것인가요?","options":[{"t":"인형극","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"일기","mis":"K2-1-u8-X01"}],"explanation":["인형이 나와 이야기를 보여 주는 것이 인형극이에요.","시는 리듬을 살려 낭송하는 작품이에요.","일기는 내가 겪은 일을 쓴 글이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#2','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',1,'ox','auto','같은 작품을 읽어도 친구와 내 느낌이 서로 다를 수 있어요.',ARRAY['K2-1-u8-X02']::text[],true,'{"seq":2,"concept":"K2-1-u8-C1","difficulty":1,"kind":"ox","stem":"같은 작품을 읽어도 친구와 내 느낌이 서로 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 겪은 일과 생각이 달라서 느낌도 다를 수 있으니까","correct":true},{"t":"작품을 읽은 느낌은 정답이 하나뿐이니까","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["같은 이야기도 누구는 슬프고 누구는 감동적일 수 있어요.","느낌이 다른 것은 자연스러운 일이에요.","친구의 느낌도 들어 보며 감상을 나눠요."],"variant_rule":{"alt":[{"stem":"작품을 감상할 때 가장 중요한 것은 빨리 다 읽는 것이에요.","answer":"X","reason_options":[{"t":"작품을 즐기고 떠오른 느낌을 나누는 것이 가장 중요하니까","correct":true},{"t":"빨리 읽어야 감상을 잘한 것이니까","mis":"K2-1-u8-X02"}],"explanation":["감상은 작품을 즐기는 것이에요.","빨리 읽는 것보다 느낌을 떠올리는 것이 중요해요.","느낀 점을 친구와 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#3','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',1,'mc','auto','글을 읽고 답해 보세요. 박에서 쌀과 보물이 쏟아져 나올 때 흥부의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],true,'{"seq":3,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 박에서 쌀과 보물이 쏟아져 나올 때 흥부의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"깜짝 놀라고 기쁘다","correct":true},{"t":"슬프고 외롭다","mis":"K2-1-u8-X05"},{"t":"화가 나고 억울하다","mis":"K2-1-u8-X05"}],"explanation":["배고프던 흥부네에 쌀과 보물이 쏟아졌으니 놀랍고 기뻤을 거예요.","슬프거나 화가 날 까닭이 없어요.","내가 흥부라면 어땠을지 떠올려요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 부어도 부어도 물이 줄줄 새어 나갈 때 콩쥐의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하고 막막하다","correct":true},{"t":"신나고 즐겁다","mis":"K2-1-u8-X05"},{"t":"자랑스럽다","mis":"K2-1-u8-X05"}],"explanation":["아무리 부어도 물이 차지 않으니 속상하고 막막했을 거예요.","신나거나 자랑스러울 까닭이 없어요.","내가 콩쥐라면 어땠을지 떠올려요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#4','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',1,'mc','auto','인물의 마음이 글에 직접 쓰여 있지 않을 때 무엇을 보고 마음을 상상하면 좋을까요?',ARRAY['K2-1-u8-X06']::text[],true,'{"seq":4,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"인물의 마음이 글에 직접 쓰여 있지 않을 때 무엇을 보고 마음을 상상하면 좋을까요?","options":[{"t":"인물이 처한 상황과 인물의 말·행동","correct":true},{"t":"인물이 입은 옷의 색깔","mis":"K2-1-u8-X06"},{"t":"책의 쪽수","mis":"K2-1-u8-X06"}],"explanation":["상황·말·행동에 인물의 마음이 담겨 있어요.","옷 색깔에는 마음이 드러나지 않아요.","쪽수는 마음과 상관없어요."],"variant_rule":{"alt":[{"stem":"작품 속 인물의 마음을 상상하며 읽으면 좋은 점은 무엇인가요?","options":[{"t":"작품이 더 실감 나고 재미있어져요","correct":true},{"t":"작품을 빨리 끝낼 수 있어요","mis":"K2-1-u8-X02"},{"t":"인물의 이름을 바꿀 수 있어요","mis":"K2-1-u8-X06"}],"explanation":["인물이 되어 보면 장면이 생생하게 느껴져요.","감상은 빨리 끝내는 것이 아니에요.","이름을 바꾸는 것과는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#5','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',2,'match','auto','작품과 그 특징을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C1","difficulty":2,"kind":"match","stem":"작품과 그 특징을 알맞게 이어 보세요.","pairs":[{"l":"시","r":"짧은 말에 리듬을 담아 쓴 글"},{"l":"이야기","r":"인물이 겪은 일을 차례대로 들려주는 글"},{"l":"인형극","r":"인형이 나와 말과 행동으로 보여 주는 극"}],"mis":"K2-1-u8-X01","explanation":["시는 리듬이 살아 있는 짧은 글이에요.","이야기에는 인물과 일어난 일이 있어요.","인형극은 인형이 움직이며 보여 줘요."],"variant_rule":{"alt":[{"stem":"작품과 그 작품을 즐기는 방법을 알맞게 이어 보세요.","pairs":[{"l":"시","r":"소리 내어 리듬을 살려 낭송하기"},{"l":"이야기","r":"인물의 마음을 상상하며 읽기"},{"l":"인형극","r":"인형의 움직임과 목소리를 보고 듣기"}],"explanation":["시는 소리 내어 낭송하면 더 즐거워요.","이야기는 인물이 되어 읽어 봐요.","인형극은 움직임과 목소리에 마음이 담겨 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#6','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',2,'mc','auto','글을 읽고 답해 보세요. 흥부가 무척 놀랐다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X04']::text[],true,'{"seq":6,"concept":"K2-1-u8-C2","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 흥부가 무척 놀랐다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"눈이 휘둥그레져 입을 다물지 못했어요","correct":true},{"t":"지붕 위에 커다란 박이 열렸어요","mis":"K2-1-u8-X06"},{"t":"아이들은 덩실덩실 춤을 추었어요","mis":"K2-1-u8-X04"}],"explanation":["눈이 휘둥그레지고 입을 다물지 못한 행동에 놀란 마음이 드러나요.","박이 열린 것은 일어난 일이지 흥부의 행동이 아니에요.","춤을 춘 것은 흥부가 아니라 아이들이에요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 콩쥐가 무척 속상했다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요","correct":true},{"t":"물이 찰랑찰랑 차올랐어요","mis":"K2-1-u8-X06"},{"t":"「내가 구멍을 막아 줄게.」라고 말했어요","mis":"K2-1-u8-X04"}],"explanation":["주저앉아 우는 행동에 속상한 마음이 드러나요.","물이 차오른 것은 마음이 드러나는 행동이 아니에요.","구멍을 막아 준다고 한 것은 두꺼비예요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#7','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',2,'mc','auto','글을 읽고 답해 보세요. 두꺼비를 꼭 끌어안으며 말할 때 콩쥐의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],true,'{"seq":7,"concept":"K2-1-u8-C2","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 두꺼비를 꼭 끌어안으며 말할 때 콩쥐의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"고맙고 기쁘다","correct":true},{"t":"무섭고 싫다","mis":"K2-1-u8-X05"},{"t":"미안하고 부끄럽다","mis":"K2-1-u8-X05"}],"explanation":["어려울 때 도와준 두꺼비가 고마웠을 거예요.","싫었다면 꼭 끌어안지 않았을 거예요.","콩쥐가 잘못한 일은 없어요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 서로 얼싸안고 덩실덩실 춤을 출 때 흥부네 아이들의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"기쁘고 신나다","correct":true},{"t":"무섭고 떨리다","mis":"K2-1-u8-X05"},{"t":"졸리고 심심하다","mis":"K2-1-u8-X05"}],"explanation":["배고프던 아이들에게 쌀이 생겨 기쁘고 신났을 거예요.","무서웠다면 춤을 추지 않았을 거예요.","졸리거나 심심할 까닭이 없어요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#8','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',2,'error','auto','글을 읽고 콩쥐의 마음을 상상했어요. 잘못 상상한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C2","difficulty":2,"kind":"error","stem":"글을 읽고 콩쥐의 마음을 상상했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"하린 — 「물이 새어 나갈 때 콩쥐는 신이 났을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"지안 — 「물이 새어 나갈 때 콩쥐는 막막했을 거야.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「두꺼비가 나타났을 때 콩쥐는 안심이 됐을 거야.」","mis":"K2-1-u8-X19"}],"explanation":["물이 자꾸 새는데 신이 났을 리 없어요. 콩쥐는 울고 있었어요.","지안이와 윤호는 상황에 맞게 상상했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 흥부의 마음을 상상했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"도담 — 「보물이 쏟아질 때 흥부는 실망했을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"소율 — 「보물이 쏟아질 때 흥부는 꿈인가 싶었을 거야.」","mis":"K2-1-u8-X19"},{"t":"민호 — 「박을 탈 때 흥부는 무엇이 나올지 설렜을 거야.」","mis":"K2-1-u8-X19"}],"explanation":["입을 다물지 못할 만큼 놀란 흥부가 실망했을 리 없어요.","소율이와 민호는 상황에 맞게 상상했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#9','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C1',2,'sa','auto','짧은 말에 리듬을 담아 쓰고 소리 내어 낭송하는 작품을 한 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C1","difficulty":2,"kind":"sa","stem":"짧은 말에 리듬을 담아 쓰고 소리 내어 낭송하는 작품을 한 글자로 써 보세요.","answer":["시"],"explanation":["시는 낭송하며 리듬을 즐기는 작품이에요.","짧은 말 속에 느낌이 담겨 있어요.","이 단원에서 「손 흔들기」 같은 시를 만나요."],"variant_rule":{"alt":[{"stem":"인형이 나와 말과 행동으로 이야기를 보여 주는 작품을 세 글자로 써 보세요.","answer":["인형극"],"explanation":["인형이 나와 보여 주는 극이 인형극이에요.","인형의 목소리와 움직임으로 이야기를 보여 줘요.","그림자·막대·손가락 인형극이 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_basic#10','kor',2,1,'u8','L01','g2_1_kor_u8_L01_basic','lesson_basic','K2-1-u8-C2',3,'mc','auto','글을 읽고 답해 보세요. 내가 흥부라면 박이 쩍 갈라지는 순간 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X03']::text[],true,'{"seq":10,"concept":"K2-1-u8-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 내가 흥부라면 박이 쩍 갈라지는 순간 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 이게 다 뭐야! 꿈만 같아!」","correct":true},{"t":"「박이 무거워서 귀찮기만 하네.」","mis":"K2-1-u8-X05"},{"t":"「아이들아, 울지 마라. 다 괜찮다.」","mis":"K2-1-u8-X03"}],"explanation":["쌀과 보물이 쏟아지는 놀랍고 기쁜 순간에 어울리는 말이에요.","귀찮아하는 마음은 이 장면과 맞지 않아요.","아이들은 울지 않고 춤을 추었어요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 내가 콩쥐라면 두꺼비가 구멍을 막아 줄 때 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「두꺼비야, 덕분에 물을 채울 수 있겠어!」","correct":true},{"t":"「두꺼비는 무서우니까 저리 가!」","mis":"K2-1-u8-X05"},{"t":"「새어머니, 고맙습니다!」","mis":"K2-1-u8-X04"}],"explanation":["도와준 두꺼비에게 고마운 마음을 전하는 말이에요.","콩쥐는 두꺼비를 꼭 끌어안았으니 무서워하지 않았어요.","구멍을 막아 준 것은 새어머니가 아니라 두꺼비예요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#1','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',2,'mc','auto','작품을 감상한 경험을 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":2,"kind":"mc","stem":"작품을 감상한 경험을 말한 친구는 누구인가요?","options":[{"t":"서아 — 「도서관에서 이야기책을 읽고 주인공이 불쌍해서 눈물이 났어.」","correct":true},{"t":"준우 — 「어제 내 책상 서랍을 정리했어.」","mis":"K2-1-u8-X01"},{"t":"하늘 — 「문구점에서 인형을 하나 샀어.」","mis":"K2-1-u8-X01"}],"explanation":["작품을 읽고 느낌이 떠오른 경험이에요.","서랍 정리는 작품 감상이 아니에요.","인형을 산 일은 인형극을 본 경험이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#2','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',2,'mc','auto','글을 읽고 답해 보세요. 새어머니가 콩쥐에게 시킨 일은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 새어머니가 콩쥐에게 시킨 일은 무엇인가요?","options":[{"t":"밑 빠진 독에 물을 가득 채우기","correct":true},{"t":"볏단을 옮기기","mis":"K2-1-u8-X03"},{"t":"박을 타기","mis":"K2-1-u8-X03"}],"explanation":["새어머니는 밑 빠진 독에 물을 채우라고 했어요.","볏단을 옮기는 일은 다른 옛이야기에 나와요.","박을 탄 것은 흥부네예요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#3','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',3,'ox','auto','같은 작품을 보고 친구가 나와 다르게 느꼈다면 친구의 감상이 틀린 거예요.',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":3,"concept":"K2-1-u8-C1","difficulty":3,"kind":"ox","stem":"같은 작품을 보고 친구가 나와 다르게 느꼈다면 친구의 감상이 틀린 거예요.","answer":"X","reason_options":[{"t":"겪은 일과 생각이 달라 느낌이 다를 수 있으니까","correct":true},{"t":"작품의 느낌은 하나로 정해져 있으니까","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["느낌이 다른 것은 틀린 것이 아니에요.","친구의 느낌을 들으면 작품을 더 넓게 볼 수 있어요.","서로의 감상을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#4','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',3,'mc','auto','글을 읽고 답해 보세요. 「슬근슬근 톱질하세!」 노래하며 박을 탈 때 흥부와 아내의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":4,"concept":"K2-1-u8-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「슬근슬근 톱질하세!」 노래하며 박을 탈 때 흥부와 아내의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무엇이 나올지 설레고 즐겁다","correct":true},{"t":"지루하고 하기 싫다","mis":"K2-1-u8-X05"},{"t":"무섭고 걱정된다","mis":"K2-1-u8-X05"}],"explanation":["노래를 부르며 박을 탔으니 설레고 즐거웠을 거예요.","하기 싫었다면 노래하지 않았을 거예요.","노래하는 모습에서 무서운 마음은 보이지 않아요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#5','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',3,'error','auto','글을 읽고 흥부의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X19']::text[],false,'{"seq":5,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 흥부의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?","options":[{"t":"채원 — 「흥부는 기뻤을 거야. 박이 지붕 위에 열렸으니까.」","correct":true,"mis_target":"K2-1-u8-X06"},{"t":"하준 — 「흥부는 놀랐을 거야. 눈이 휘둥그레졌으니까.」","mis":"K2-1-u8-X19"},{"t":"지우 — 「흥부는 기뻤을 거야. 배고프던 식구가 쌀을 얻었으니까.」","mis":"K2-1-u8-X19"}],"explanation":["박이 지붕에 열린 것만으로는 흥부의 기쁨이 드러나지 않아요.","하준이와 지우는 행동과 상황을 까닭으로 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#6','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',3,'mc','auto','글을 읽고 답해 보세요. 콩쥐의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":6,"concept":"K2-1-u8-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 콩쥐의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하고 막막하다 → 고맙고 기쁘다","correct":true},{"t":"고맙고 기쁘다 → 속상하고 막막하다","mis":"K2-1-u8-X09"},{"t":"처음부터 끝까지 신나고 즐겁다","mis":"K2-1-u8-X09"}],"explanation":["물이 새어 나갈 때는 속상했고 두꺼비가 도와준 뒤에는 고마웠어요.","차례가 거꾸로 되었어요.","콩쥐의 마음은 도중에 바뀌었어요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#7','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',3,'mc','auto','이 단원에서 작품을 감상할 때 가장 중요한 것은 무엇인가요?',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":7,"concept":"K2-1-u8-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 작품을 감상할 때 가장 중요한 것은 무엇인가요?","options":[{"t":"작품을 즐기고 떠오른 느낌을 친구와 나누기","correct":true},{"t":"틀리지 않고 빠르게 읽기","mis":"K2-1-u8-X02"},{"t":"작품을 그대로 외워서 말하기","mis":"K2-1-u8-X02"}],"explanation":["감상의 핵심은 즐기고 나누는 것이에요.","빨리 읽는 것은 감상의 목표가 아니에요.","외우는 것보다 내 느낌을 말하는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#8','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',4,'mc','auto','글을 읽고 답해 보세요. 콩쥐의 마음을 알맞게 짐작하고 까닭도 바르게 든 것은 어느 것인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":8,"concept":"K2-1-u8-C2","difficulty":4,"kind":"mc","stem":"글을 읽고 답해 보세요. 콩쥐의 마음을 알맞게 짐작하고 까닭도 바르게 든 것은 어느 것인가요?","options":[{"t":"「고마웠을 거야. 어려울 때 도와준 두꺼비를 꼭 끌어안았으니까.」","correct":true},{"t":"「무서웠을 거야. 두꺼비가 커다랬으니까.」","mis":"K2-1-u8-X05"},{"t":"「심심했을 거야. 물을 다 채워서 할 일이 없었으니까.」","mis":"K2-1-u8-X06"}],"explanation":["끌어안는 행동과 고맙다는 말에 마음이 드러나요.","콩쥐는 두꺼비를 무서워하지 않고 끌어안았어요.","물을 다 채운 것과 심심한 마음은 이 장면에서 드러나지 않아요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#9','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C2',4,'essay','teacher','글을 읽고 답해 보세요. 내가 흥부라면 박에서 쌀과 보물이 쏟아질 때 어떤 마음이었을지 쓰고, 그렇게 생각한 까닭을 글 속 상황이나 말·행동을 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C2","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 내가 흥부라면 박에서 쌀과 보물이 쏟아질 때 어떤 마음이었을지 쓰고, 그렇게 생각한 까닭을 글 속 상황이나 말·행동을 들어 써 보세요.","answer_guide":{"answer":"예: 너무 놀라서 꿈인지 생시인지 몰랐을 것 같아요. 왜냐하면 흥부가 눈이 휘둥그레져 입을 다물지 못했고, 늘 배고프던 아이들이 이제 배불리 먹을 수 있게 되었기 때문이에요.","scoring_points":["흥부의 마음을 썼는가","글 속 상황이나 말·행동을 까닭으로 들었는가","글에 없는 내용을 지어내지 않았는가"]},"explanation":["흥부의 마음.","상황·말·행동을 든 까닭.","글에 있는 내용."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L01_challenge#10','kor',2,1,'u8','L01','g2_1_kor_u8_L01_challenge','lesson_challenge','K2-1-u8-C1',4,'essay','teacher','시·이야기·인형극 가운데 내가 감상해 본 작품 하나를 떠올려 무엇을 어디에서 감상했는지와 그때 떠오른 느낌을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C1","difficulty":4,"kind":"essay","stem":"시·이야기·인형극 가운데 내가 감상해 본 작품 하나를 떠올려 무엇을 어디에서 감상했는지와 그때 떠오른 느낌을 써 보세요.","answer_guide":{"answer":"예: 지난 여름 도서관에서 그림자 인형극 「해와 달이 된 오누이」를 보았어요. 호랑이 그림자가 커다랗게 나타날 때 가슴이 콩닥콩닥 뛰었고, 오누이가 하늘로 올라갈 때는 안심이 되었어요.","scoring_points":["감상한 작품을 밝혔는가","어디에서 감상했는지 썼는가","그때 떠오른 느낌을 썼는가"]},"explanation":["감상한 작품.","감상한 곳.","떠오른 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#1','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',1,'mc','auto','시를 읽고 답해 보세요. 짝꿍이 학교 앞에서 한 행동은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":1,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 짝꿍이 학교 앞에서 한 행동은 무엇인가요?","options":[{"t":"손을 흔들었어요","correct":true},{"t":"노래를 불렀어요","mis":"K2-1-u8-X03"},{"t":"편지를 건넸어요","mis":"K2-1-u8-X03"}],"explanation":["「짝꿍이 손을 흔든다」라고 했어요.","노래를 불렀다는 말은 시에 없어요.","편지를 건넸다는 말도 없어요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 「나」가 잠든 동생에게 한 행동은 무엇인가요?","options":[{"t":"이불을 살며시 덮어 주었어요","correct":true},{"t":"책을 읽어 주었어요","mis":"K2-1-u8-X03"},{"t":"흔들어 깨웠어요","mis":"K2-1-u8-X03"}],"explanation":["「이불을 살며시 덮어 준다」라고 했어요.","책을 읽어 주었다는 말은 시에 없어요.","깰까 봐 조심했으니 깨우지 않았어요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#2','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',1,'mc','auto','시를 읽고 답해 보세요. 짝꿍을 본 「나」의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],true,'{"seq":2,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 짝꿍을 본 「나」의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"반갑다","correct":true},{"t":"무섭다","mis":"K2-1-u8-X05"},{"t":"졸리다","mis":"K2-1-u8-X05"}],"explanation":["두 팔을 번쩍 들어 손을 흔드는 행동에 반가운 마음이 담겨 있어요.","무서웠다면 손을 흔들지 않았을 거예요.","졸린 마음은 시에서 보이지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 잠든 동생을 보는 「나」의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"동생을 아끼는 마음","correct":true},{"t":"동생이 귀찮은 마음","mis":"K2-1-u8-X05"},{"t":"동생에게 화난 마음","mis":"K2-1-u8-X05"}],"explanation":["이불을 덮어 주고 숨도 조용히 쉬는 행동에 아끼는 마음이 담겨 있어요.","귀찮았다면 이렇게 조심하지 않았을 거예요.","화난 모습은 시에 없어요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#3','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',1,'ox','auto','시를 낭송할 때는 시의 리듬과 느낌을 살려 소리 내어 읽어요.',ARRAY['K2-1-u8-X08']::text[],true,'{"seq":3,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"시를 낭송할 때는 시의 리듬과 느낌을 살려 소리 내어 읽어요.","answer":"O","reason_options":[{"t":"리듬과 느낌을 살리면 시가 더 생생하게 느껴지니까","correct":true},{"t":"시는 언제나 크고 빠르게만 읽어야 하니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["소리 내어 리듬을 살리면 시가 살아나요.","시마다 어울리는 목소리가 달라요.","느낌을 살려 즐겁게 낭송해요."],"variant_rule":{"alt":[{"stem":"시 낭송은 한 가지 방법으로만 해야 해요.","answer":"X","reason_options":[{"t":"주고받기·몸짓 넣기·박자 넣기처럼 여러 방법으로 낭송할 수 있으니까","correct":true},{"t":"다른 방법으로 읽으면 시가 틀리게 되니까","mis":"K2-1-u8-X08"}],"explanation":["시는 여러 방법으로 낭송할 수 있어요.","방법을 바꾸면 느낌이 새롭게 달라져요.","친구와 함께 여러 방법으로 즐겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#4','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',1,'mc','auto','시를 읽고 답해 보세요. 모양을 흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],true,'{"seq":4,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 모양을 흉내 내는 말은 어느 것인가요?","options":[{"t":"흔들흔들","correct":true},{"t":"짝꿍","mis":"K2-1-u8-X07"},{"t":"학교","mis":"K2-1-u8-X07"}],"explanation":["「흔들흔들」은 손이 이리저리 움직이는 모양을 흉내 낸 말이에요.","「짝꿍」은 사람을 나타내는 말이에요.","「학교」는 곳을 나타내는 말이에요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 모양을 흉내 내는 말은 어느 것인가요?","options":[{"t":"살금살금","correct":true},{"t":"동생","mis":"K2-1-u8-X07"},{"t":"이불","mis":"K2-1-u8-X07"}],"explanation":["「살금살금」은 남이 모르게 조용히 걷는 모양을 흉내 낸 말이에요.","「동생」은 사람을 나타내는 말이에요.","「이불」은 물건을 나타내는 말이에요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#5','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',2,'match','auto','흉내 내는 말과 그 뜻을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C4","difficulty":2,"kind":"match","stem":"흉내 내는 말과 그 뜻을 알맞게 이어 보세요.","pairs":[{"l":"살금살금","r":"남이 모르게 조용히 걷는 모양"},{"l":"새근새근","r":"곱게 잠들어 고르게 숨 쉬는 소리"},{"l":"번쩍","r":"팔을 높이 빠르게 드는 모양"}],"mis":"K2-1-u8-X07","explanation":["「살금살금」은 조용히 걷는 모양이에요.","「새근새근」은 곤히 자며 숨 쉬는 소리예요.","「번쩍」은 높이 빠르게 드는 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 흉내 내는 말과 그 뜻을 알맞게 이어 보세요.","pairs":[{"l":"흔들흔들","r":"이리저리 자꾸 움직이는 모양"},{"l":"조용조용","r":"소리가 나지 않게 아주 조용한 모양"},{"l":"활짝","r":"웃음이 환하게 피어나는 모양"}],"explanation":["「흔들흔들」은 이리저리 움직이는 모양이에요.","「조용조용」은 소리 없이 조용한 모양이에요.","「활짝」은 환하게 웃는 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#6','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「말 한마디 안 했는데 / 우리 둘은 벌써 웃는다」에서 알 수 있는 것은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X03']::text[],true,'{"seq":6,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「말 한마디 안 했는데 / 우리 둘은 벌써 웃는다」에서 알 수 있는 것은 무엇인가요?","options":[{"t":"말하지 않아도 손 흔드는 행동으로 반가운 마음이 전해졌어요","correct":true},{"t":"둘은 서로 말다툼을 했어요","mis":"K2-1-u8-X05"},{"t":"둘은 서로 모르는 사이예요","mis":"K2-1-u8-X03"}],"explanation":["손을 흔드는 행동만으로 마음이 통했어요.","다툰 친구라면 웃지 않았을 거예요.","시에서 「짝꿍」이라고 했으니 아는 사이예요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 「혹시 깰까 봐 / 숨도 조용조용 쉰다」에서 알 수 있는 「나」의 마음은 무엇인가요?","options":[{"t":"동생이 푹 자기를 바라는 마음","correct":true},{"t":"동생을 깨우고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"혼자 있어 무서운 마음","mis":"K2-1-u8-X05"}],"explanation":["깰까 봐 숨까지 조심하는 행동에 동생을 위하는 마음이 보여요.","깨우고 싶었다면 조심하지 않았을 거예요.","무서운 마음은 시에서 보이지 않아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#7','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',2,'mc','auto','시 낭송 방법 가운데 「주고받기」는 어떻게 읽는 것인가요?',ARRAY['K2-1-u8-X08']::text[],true,'{"seq":7,"concept":"K2-1-u8-C3","difficulty":2,"kind":"mc","stem":"시 낭송 방법 가운데 「주고받기」는 어떻게 읽는 것인가요?","options":[{"t":"두 사람이나 두 모둠이 한 줄씩 번갈아 읽어요","correct":true},{"t":"혼자 속으로 조용히 읽어요","mis":"K2-1-u8-X08"},{"t":"모두가 한꺼번에 소리쳐 읽어요","mis":"K2-1-u8-X08"}],"explanation":["주고받기는 번갈아 가며 읽는 방법이에요.","속으로 읽으면 낭송이 아니에요.","한꺼번에 소리치면 주고받기가 아니에요."],"variant_rule":{"alt":[{"stem":"시 낭송 방법 가운데 「몸짓 넣기」는 어떻게 읽는 것인가요?","options":[{"t":"시 내용에 어울리는 몸짓을 하며 읽어요","correct":true},{"t":"눈을 감고 가만히 읽어요","mis":"K2-1-u8-X08"},{"t":"최대한 빠르게 읽어요","mis":"K2-1-u8-X08"}],"explanation":["몸짓을 넣으면 시의 장면이 눈에 보이듯 살아나요.","가만히 읽으면 몸짓 넣기가 아니에요.","빠르게 읽는 것은 몸짓 넣기와 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#8','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',2,'error','auto','시 「동생이 잠든 밤」을 낭송했어요. 시의 분위기와 어울리지 않게 낭송한 친구는 누구인가요?',ARRAY['K2-1-u8-X08','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":2,"kind":"error","stem":"시 「동생이 잠든 밤」을 낭송했어요. 시의 분위기와 어울리지 않게 낭송한 친구는 누구인가요?","options":[{"t":"하람 — 큰 소리로 외치듯 빠르게 읽었어요","correct":true,"mis_target":"K2-1-u8-X08"},{"t":"서아 — 속삭이듯 작은 목소리로 천천히 읽었어요","mis":"K2-1-u8-X19"},{"t":"윤서 — 「살금살금」에서 발끝으로 걷는 몸짓을 했어요","mis":"K2-1-u8-X19"}],"explanation":["동생이 잠든 조용한 밤의 시는 크게 외치면 분위기가 깨져요.","서아와 윤서는 시의 분위기를 살렸어요.","물음의 「어울리지 않게」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"},"variant_rule":{"alt":[{"stem":"시 「손 흔들기」를 낭송했어요. 시의 분위기와 어울리지 않게 낭송한 친구는 누구인가요?","options":[{"t":"민호 — 「번쩍」에서 팔을 아래로 축 늘어뜨렸어요","correct":true,"mis_target":"K2-1-u8-X08"},{"t":"지우 — 「흔들흔들」에서 손을 흔들며 밝게 읽었어요","mis":"K2-1-u8-X19"},{"t":"하늘 — 짝과 두 줄씩 주고받으며 읽었어요","mis":"K2-1-u8-X19"}],"explanation":["「번쩍」은 팔을 높이 드는 모양이라 축 늘어뜨리면 맞지 않아요.","지우와 하늘이는 시의 분위기를 살렸어요.","물음의 「어울리지 않게」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#9','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C4',2,'sa','auto','시를 읽고 답해 보세요. 「나」가 짝꿍을 보고 번쩍 든 것을 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"sa","stem":"시를 읽고 답해 보세요. 「나」가 짝꿍을 보고 번쩍 든 것을 써 보세요.","answer":["두 팔","두팔","팔"],"explanation":["「나도 두 팔을 번쩍 들어」라고 했어요.","두 팔을 들어 흔들며 반가움을 나타냈어요.","시에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 「나」가 동생에게 살며시 덮어 준 것을 두 글자로 써 보세요.","answer":["이불"],"explanation":["「이불을 살며시 덮어 준다」라고 했어요.","동생이 춥지 않게 덮어 주었어요.","시에서 그 줄을 찾아 짚어요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_basic#10','kor',2,1,'u8','L03','g2_1_kor_u8_L03_basic','lesson_basic','K2-1-u8-C3',3,'mc','auto','같은 시라도 낭송하는 방법을 바꾸면 어떻게 될까요?',ARRAY['K2-1-u8-X08']::text[],true,'{"seq":10,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"같은 시라도 낭송하는 방법을 바꾸면 어떻게 될까요?","options":[{"t":"느낌이 달라져서 시를 더 여러 가지로 즐길 수 있어요","correct":true},{"t":"시의 내용이 다른 이야기로 바뀌어요","mis":"K2-1-u8-X08"},{"t":"시가 틀린 시가 돼요","mis":"K2-1-u8-X08"}],"explanation":["낭송 방법을 바꾸면 같은 시도 새롭게 느껴져요.","읽는 방법이 바뀌어도 시의 내용은 그대로예요.","방법을 바꾼다고 시가 틀려지지 않아요."],"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시를 더 실감 나게 낭송하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「흔들흔들」에서 손을 흔들며 밝은 목소리로 읽기","correct":true},{"t":"졸린 목소리로 작게 웅얼거리기","mis":"K2-1-u8-X08"},{"t":"고개를 숙인 채 아주 빠르게 읽기","mis":"K2-1-u8-X08"}],"explanation":["반가운 마음이 담긴 시라 밝은 목소리와 손 흔들기가 어울려요.","졸린 목소리는 반가운 분위기와 맞지 않아요.","고개를 숙이고 빠르게 읽으면 느낌이 살지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#1','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「나」는 동생에게 어떻게 다가갔나요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":1,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나」는 동생에게 어떻게 다가갔나요?","options":[{"t":"살금살금","correct":true},{"t":"깡충깡충","mis":"K2-1-u8-X07"},{"t":"쿵쾅쿵쾅","mis":"K2-1-u8-X07"}],"explanation":["「살금살금 다가가」라고 했어요.","「깡충깡충」은 뛰는 모양이에요.","「쿵쾅쿵쾅」은 시끄럽게 걷는 소리라 동생이 깰 거예요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#2','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',2,'mc','auto','시 낭송 방법 가운데 「박자 넣기」는 어떻게 읽는 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":2,"concept":"K2-1-u8-C3","difficulty":2,"kind":"mc","stem":"시 낭송 방법 가운데 「박자 넣기」는 어떻게 읽는 것인가요?","options":[{"t":"손뼉이나 발 구르기로 박자를 맞추며 읽어요","correct":true},{"t":"한 줄씩 번갈아 읽어요","mis":"K2-1-u8-X08"},{"t":"그림을 그리며 읽어요","mis":"K2-1-u8-X08"}],"explanation":["박자를 넣으면 시의 리듬이 또렷해져요.","번갈아 읽는 것은 주고받기예요.","그림 그리기는 박자 넣기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#3','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'mc','auto','시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」의 「번쩍」은 「나」의 어떤 마음을 잘 나타내나요?',ARRAY['K2-1-u8-X07','K2-1-u8-X05']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」의 「번쩍」은 「나」의 어떤 마음을 잘 나타내나요?","options":[{"t":"무척 반가워서 힘차게 답하고 싶은 마음","correct":true},{"t":"귀찮아서 마지못해 답하는 마음","mis":"K2-1-u8-X07"},{"t":"겁이 나서 숨고 싶은 마음","mis":"K2-1-u8-X05"}],"explanation":["팔을 높이 빠르게 드는 모양에 큰 반가움이 담겨 있어요.","마지못해 한다면 팔을 번쩍 들지 않았을 거예요.","숨고 싶은 마음은 시에서 보이지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#4','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'error','auto','시를 읽고 「나」의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C4","difficulty":3,"kind":"error","stem":"시를 읽고 「나」의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"예린 — 「동생이 미웠을 거야. 숨도 조용조용 쉬었으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"건우 — 「동생을 아꼈을 거야. 이불을 살며시 덮어 줬으니까.」","mis":"K2-1-u8-X19"},{"t":"채원 — 「동생이 깰까 봐 조심스러웠을 거야. 살금살금 다가갔으니까.」","mis":"K2-1-u8-X19"}],"explanation":["숨까지 조용히 쉰 것은 동생을 위해서지 미워서가 아니에요.","건우와 채원이는 행동에 맞게 짐작했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#5','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'ox','auto','시에 「반갑다」라는 말이 없으면 「나」가 반가웠는지 알 수 없어요.',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":5,"concept":"K2-1-u8-C4","difficulty":3,"kind":"ox","stem":"시에 「반갑다」라는 말이 없으면 「나」가 반가웠는지 알 수 없어요.","answer":"X","reason_options":[{"t":"웃으며 손을 흔드는 행동에서 반가운 마음을 짐작할 수 있으니까","correct":true},{"t":"마음은 글에 쓰인 말로만 알 수 있으니까","mis":"K2-1-u8-X05"}],"mis":"K2-1-u8-X05","explanation":["행동 속에 마음이 담겨 있어요.","「번쩍」·「흔들흔들」·「웃는다」에서 반가움이 느껴져요.","말이 없어도 행동을 보고 마음을 짐작해요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#6','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":6,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 목소리는 어느 것인가요?","options":[{"t":"작고 부드러운 목소리로 천천히","correct":true},{"t":"크고 씩씩한 목소리로 빠르게","mis":"K2-1-u8-X08"},{"t":"화난 목소리로 또박또박 끊어서","mis":"K2-1-u8-X08"}],"explanation":["동생이 잠든 고요한 밤이라 작고 부드럽게 읽으면 어울려요.","크고 빠르게 읽으면 조용한 분위기가 깨져요.","화난 목소리는 동생을 아끼는 마음과 맞지 않아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#7','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',3,'mc','auto','시를 읽고 답해 보세요. 「나」처럼 말없이 몸짓으로 마음을 주고받은 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":7,"concept":"K2-1-u8-C4","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나」처럼 말없이 몸짓으로 마음을 주고받은 경험을 떠올린 친구는 누구인가요?","options":[{"t":"다은 — 「달리기 때 멀리서 엄마가 엄지를 척 들어 줘서 힘이 났어.」","correct":true},{"t":"준우 — 「나는 어제 혼자 숙제를 했어.」","mis":"K2-1-u8-X06"},{"t":"소율 — 「우리 학교 앞에는 문구점이 있어.」","mis":"K2-1-u8-X06"}],"explanation":["말 대신 몸짓으로 마음이 전해진 경험이에요.","혼자 숙제한 일은 몸짓으로 마음을 주고받은 경험이 아니에요.","학교 앞 문구점은 시와 상관없는 이야기예요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#8','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',4,'mc','auto','시를 읽고 답해 보세요. 친구와 둘이 「주고받기」로 낭송하려고 해요. 가장 알맞게 나눈 것은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":4,"kind":"mc","stem":"시를 읽고 답해 보세요. 친구와 둘이 「주고받기」로 낭송하려고 해요. 가장 알맞게 나눈 것은 어느 것인가요?","options":[{"t":"짝꿍 역은 1·2행, 나 역은 3·4행을 읽고 마지막 두 행은 함께 읽어요","correct":true},{"t":"한 사람이 처음부터 끝까지 혼자 다 읽어요","mis":"K2-1-u8-X08"},{"t":"두 사람이 같은 행을 서로 먼저 읽으려고 겹쳐 읽어요","mis":"K2-1-u8-X08"}],"explanation":["짝꿍이 손 흔드는 줄과 내가 답하는 줄을 나누니 주고받는 느낌이 살아요.","혼자 다 읽으면 주고받기가 아니에요.","겹쳐 읽으면 무슨 말인지 들리지 않아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#9','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C4',4,'essay','teacher','시를 읽고 답해 보세요. 「나」의 마음을 짐작해 쓰고, 그렇게 짐작할 수 있는 행동이나 흉내 내는 말을 시에서 두 가지 찾아 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 「나」의 마음을 짐작해 쓰고, 그렇게 짐작할 수 있는 행동이나 흉내 내는 말을 시에서 두 가지 찾아 써 보세요.","answer_guide":{"answer":"예: 「나」는 동생을 아끼고 동생이 푹 자기를 바랐을 거예요. 「살금살금 다가가」와 「숨도 조용조용 쉰다」에서 동생이 깰까 봐 조심하는 마음을 알 수 있어요.","scoring_points":["「나」의 마음을 썼는가","시에서 행동이나 흉내 내는 말을 두 가지 찾았는가","찾은 부분과 마음이 서로 맞는가"]},"explanation":["「나」의 마음.","행동·흉내 내는 말 두 가지.","마음과 근거가 맞는지."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L03_challenge#10','kor',2,1,'u8','L03','g2_1_kor_u8_L03_challenge','lesson_challenge','K2-1-u8-C3',4,'essay','teacher','시 「손 흔들기」처럼 말없이 몸짓으로 마음을 주고받고 싶은 사람을 떠올려, 누구와 어떤 몸짓 신호로 어떤 마음을 전하고 싶은지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C3","difficulty":4,"kind":"essay","stem":"시 「손 흔들기」처럼 말없이 몸짓으로 마음을 주고받고 싶은 사람을 떠올려, 누구와 어떤 몸짓 신호로 어떤 마음을 전하고 싶은지 써 보세요.","answer_guide":{"answer":"예: 할머니와 손가락 하트 신호를 주고받고 싶어요. 할머니 댁에서 돌아올 때 차 안에서 손가락 하트를 보내 「사랑해요, 또 올게요.」라는 마음을 전하고 싶어요.","scoring_points":["누구와 주고받고 싶은지 썼는가","어떤 몸짓 신호인지 썼는가","전하고 싶은 마음을 썼는가"]},"explanation":["누구와.","몸짓 신호.","전하고 싶은 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#1','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 보보가 도시락 뚜껑을 열다가 깜짝 놀란 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":1,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보가 도시락 뚜껑을 열다가 깜짝 놀란 까닭은 무엇인가요?","options":[{"t":"도시락이 텅 비어 있어서","correct":true},{"t":"소풍이 취소되어서","mis":"K2-1-u8-X03"},{"t":"친구들이 놀려서","mis":"K2-1-u8-X03"}],"explanation":["도시락이 텅 비어 있었다고 했어요.","소풍은 취소되지 않았어요.","친구들은 놀리지 않고 음식을 나눠 주었어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이가 발을 동동 구른 까닭은 무엇인가요?","options":[{"t":"종이배가 돌에 걸려 뒤집혀서","correct":true},{"t":"오빠가 종이배를 가져가서","mis":"K2-1-u8-X03"},{"t":"갑자기 비가 와서","mis":"K2-1-u8-X03"}],"explanation":["종이배가 돌에 걸려 뒤집혔다고 했어요.","오빠는 종이배를 가져가지 않았어요.","비가 왔다는 말은 없어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#2','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내밀며 같이 먹자고 한 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],true,'{"seq":2,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내밀며 같이 먹자고 한 인물은 누구인가요?","options":[{"t":"토토","correct":true},{"t":"다미","mis":"K2-1-u8-X04"},{"t":"엄마 곰","mis":"K2-1-u8-X03"}],"explanation":["토끼 토토가 김밥을 내밀었어요.","다미는 도토리 빵을 나누어 주었어요.","엄마 곰은 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 「이번엔 더 튼튼하게 같이 접어 보자.」라고 말한 인물은 누구인가요?","options":[{"t":"오빠","correct":true},{"t":"연이","mis":"K2-1-u8-X04"},{"t":"엄마","mis":"K2-1-u8-X03"}],"explanation":["오빠가 빙그레 웃으며 그렇게 말했어요.","연이는 발을 동동 구르던 인물이에요.","엄마는 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#3','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',1,'ox','auto','이야기를 읽고 답해 보세요. 보보는 소풍이 끝날 때까지 혼자 시무룩해 있었어요.',ARRAY['K2-1-u8-X09']::text[],true,'{"seq":3,"concept":"K2-1-u8-C5","difficulty":1,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 보보는 소풍이 끝날 때까지 혼자 시무룩해 있었어요.","answer":"X","reason_options":[{"t":"친구들이 음식을 나눠 주자 활짝 웃었다고 했으니까","correct":true},{"t":"보보의 마음은 처음부터 끝까지 그대로였으니까","mis":"K2-1-u8-X09"}],"mis":"K2-1-u8-X09","explanation":["처음에는 시무룩했지만 친구들 덕분에 활짝 웃었어요.","인물의 마음은 일이 일어나며 바뀌어요.","처음·끝 장면의 마음을 따로 살펴요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이는 새 종이배가 멀리 떠내려가자 무척 기뻐했어요.","answer":"O","reason_options":[{"t":"손뼉을 치며 깡충깡충 뛰었다고 했으니까","correct":true},{"t":"연이는 끝까지 속상한 마음이었으니까","mis":"K2-1-u8-X09"}],"explanation":["손뼉 치고 깡충깡충 뛴 행동에 기쁨이 드러나요.","속상했던 마음이 기쁨으로 바뀌었어요.","처음·끝 장면의 마음을 따로 살펴요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#4','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C6',1,'mc','auto','이야기를 읽고 생각이나 느낌을 표현하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X10']::text[],true,'{"seq":4,"concept":"K2-1-u8-C6","difficulty":1,"kind":"mc","stem":"이야기를 읽고 생각이나 느낌을 표현하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"기억에 남는 장면을 그림으로 그리고 느낌을 한 줄 쓰기","correct":true},{"t":"이야기 글자 수를 세어 쓰기","mis":"K2-1-u8-X10"},{"t":"책 표지만 똑같이 따라 그리기","mis":"K2-1-u8-X10"}],"explanation":["장면과 느낌을 함께 담으면 감상이 잘 드러나요.","글자 수는 느낌과 상관없어요.","표지만 따라 그리면 내 느낌이 드러나지 않아요."],"variant_rule":{"alt":[{"stem":"기억에 남는 장면을 말할 때 함께 말하면 좋은 것은 무엇인가요?","options":[{"t":"그 장면이 기억에 남는 까닭","correct":true},{"t":"책을 산 가게 이름","mis":"K2-1-u8-X10"},{"t":"책의 무게","mis":"K2-1-u8-X10"}],"explanation":["까닭을 함께 말하면 내 느낌이 잘 전해져요.","가게 이름은 감상과 상관없어요.","책의 무게도 감상과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#5','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'match','auto','이야기를 읽고 장면과 그때 보보의 마음을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C5","difficulty":2,"kind":"match","stem":"이야기를 읽고 장면과 그때 보보의 마음을 알맞게 이어 보세요.","pairs":[{"l":"도시락이 텅 비어 있었다","r":"깜짝 놀랐다"},{"l":"나무 뒤에 혼자 앉았다","r":"시무룩하고 외로웠다"},{"l":"친구들이 음식을 나누어 주었다","r":"고맙고 기뻤다"}],"mis":"K2-1-u8-X09","explanation":["빈 도시락을 보고 깜짝 놀랐어요.","혼자 앉아 있을 때는 시무룩했어요.","친구들 덕분에 고맙고 기뻤어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 장면과 그때 연이의 마음을 알맞게 이어 보세요.","pairs":[{"l":"종이배를 시냇물에 띄웠다","r":"설레고 즐거웠다"},{"l":"종이배가 뒤집혀 젖었다","r":"속상했다"},{"l":"새 종이배가 멀리 떠내려갔다","r":"신나고 기뻤다"}],"explanation":["배를 띄울 때는 설렜어요.","배가 뒤집히자 속상했어요.","새 배가 잘 떠가자 신났어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#6','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보가 시무룩했다는 것을 알 수 있는 행동은 어느 것인가요?',ARRAY['K2-1-u8-X09','K2-1-u8-X04']::text[],true,'{"seq":6,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보가 시무룩했다는 것을 알 수 있는 행동은 어느 것인가요?","options":[{"t":"고개를 푹 숙이고 나무 뒤에 혼자 앉았어요","correct":true},{"t":"눈이 동그래졌다가 활짝 웃었어요","mis":"K2-1-u8-X09"},{"t":"깡충깡충 다가와 김밥을 내밀었어요","mis":"K2-1-u8-X04"}],"explanation":["고개를 숙이고 혼자 앉은 행동에 시무룩한 마음이 보여요.","활짝 웃은 것은 기뻐진 뒤의 모습이에요.","김밥을 내민 것은 토토예요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이가 속상했다는 것을 알 수 있는 행동은 어느 것인가요?","options":[{"t":"발을 동동 굴렀어요","correct":true},{"t":"손뼉을 치며 깡충깡충 뛰었어요","mis":"K2-1-u8-X09"},{"t":"빙그레 웃으며 말했어요","mis":"K2-1-u8-X04"}],"explanation":["발을 동동 구른 행동에 속상한 마음이 보여요.","손뼉 친 것은 기뻐진 뒤의 모습이에요.","빙그레 웃은 것은 오빠예요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#7','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],true,'{"seq":7,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"놀라고 시무룩하다 → 고맙고 기쁘다","correct":true},{"t":"고맙고 기쁘다 → 놀라고 시무룩하다","mis":"K2-1-u8-X09"},{"t":"처음부터 끝까지 고맙고 기쁘다","mis":"K2-1-u8-X09"}],"explanation":["빈 도시락에 시무룩했다가 친구들 덕분에 기뻐졌어요.","차례가 거꾸로 되었어요.","처음에는 기쁘지 않았어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"설렌다 → 속상하다 → 기쁘다","correct":true},{"t":"기쁘다 → 설렌다 → 속상하다","mis":"K2-1-u8-X09"},{"t":"속상하다 → 설렌다 → 속상하다","mis":"K2-1-u8-X09"}],"explanation":["배를 띄우며 설렜고, 뒤집히자 속상했고, 새 배가 떠가자 기뻤어요.","끝에 속상했다는 차례는 맞지 않아요.","처음부터 속상하지는 않았어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#8','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C6',2,'error','auto','「보보의 빈 도시락」에서 기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"「보보의 빈 도시락」에서 기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"지후 — 「나는 보보가 활짝 웃는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"아린 — 「다미가 빵을 나누는 장면이 기억에 남아. 자기 것도 반으로 나눠 준 게 따뜻했거든.」","mis":"K2-1-u8-X19"},{"t":"태민 — 「빈 도시락 장면이 기억에 남아. 내가 보보였으면 울었을 것 같아서.」","mis":"K2-1-u8-X19"}],"explanation":["지후는 장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","아린이와 태민이는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."],"variant_rule":{"alt":[{"stem":"「연이의 종이배」에서 기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"수빈 — 「나는 종이배가 뒤집히는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"현우 — 「오빠가 같이 접자고 하는 장면이 기억에 남아. 다정한 오빠가 부러웠거든.」","mis":"K2-1-u8-X19"},{"t":"다은 — 「새 배가 떠가는 장면이 기억에 남아. 다시 해서 해낸 게 멋졌거든.」","mis":"K2-1-u8-X19"}],"explanation":["수빈이는 장면만 말하고 까닭을 말하지 않았어요.","현우와 다은이는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#9','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C5',2,'sa','auto','이야기를 읽고 답해 보세요. 다람쥐 다미가 반으로 나누어 준 음식을 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C5","difficulty":2,"kind":"sa","stem":"이야기를 읽고 답해 보세요. 다람쥐 다미가 반으로 나누어 준 음식을 써 보세요.","answer":["도토리 빵","도토리빵"],"explanation":["다미는 도토리 빵을 반으로 나누어 주었어요.","토토는 당근 김밥을 내밀었어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 연이와 오빠가 접어 시냇물에 띄운 것을 세 글자로 써 보세요.","answer":["종이배"],"explanation":["둘은 종이배를 접어 띄웠어요.","처음 배는 뒤집혔지만 새 배는 멀리 떠갔어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_basic#10','kor',2,1,'u8','L05','g2_1_kor_u8_L05_basic','lesson_basic','K2-1-u8-C6',3,'mc','auto','이야기를 읽고 답해 보세요. 기억에 남는 장면과 까닭, 비슷한 내 경험을 모두 담아 감상을 말한 것은 어느 것인가요?',ARRAY['K2-1-u8-X10']::text[],true,'{"seq":10,"concept":"K2-1-u8-C6","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 기억에 남는 장면과 까닭, 비슷한 내 경험을 모두 담아 감상을 말한 것은 어느 것인가요?","options":[{"t":"「토토가 김밥을 내미는 장면이 기억에 남아. 먼저 다가간 토토가 멋졌거든. 나도 짝이 먼저 말을 걸어 줘서 고마웠던 적이 있어.」","correct":true},{"t":"「보보는 아기 곰이고 토토는 토끼야.」","mis":"K2-1-u8-X10"},{"t":"「소풍을 가서 도시락을 먹는 이야기야.」","mis":"K2-1-u8-X10"}],"explanation":["장면·까닭·내 경험이 모두 들어 있어요.","인물 소개만 하고 느낌은 없어요.","줄거리만 말하고 느낌은 없어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 답해 보세요. 기억에 남는 장면과 까닭, 비슷한 내 경험을 모두 담아 감상을 말한 것은 어느 것인가요?","options":[{"t":"「새 종이배가 멀리 떠가는 장면이 기억에 남아. 포기하지 않고 다시 접어서 해낸 게 좋았거든. 나도 블록 성이 무너졌을 때 다시 쌓아서 완성한 적이 있어.」","correct":true},{"t":"「연이와 오빠가 종이배를 접는 이야기야.」","mis":"K2-1-u8-X10"},{"t":"「시냇물에는 돌이 있어.」","mis":"K2-1-u8-X10"}],"explanation":["장면·까닭·내 경험이 모두 들어 있어요.","줄거리만 말하고 느낌은 없어요.","이야기 속 물건만 말했어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#1','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 연이와 오빠가 새 종이배를 더 튼튼하게 만든 방법은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":1,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이와 오빠가 새 종이배를 더 튼튼하게 만든 방법은 무엇인가요?","options":[{"t":"종이를 두 겹으로 겹쳐서 접었어요","correct":true},{"t":"배 위에 돌을 실었어요","mis":"K2-1-u8-X03"},{"t":"비닐로 겉을 감쌌어요","mis":"K2-1-u8-X03"}],"explanation":["종이를 두 겹으로 겹쳐 새 배를 접었다고 했어요.","돌을 실었다는 말은 없어요.","비닐로 감쌌다는 말도 없어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#2','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',2,'mc','auto','감상 발표를 읽고 답해 보세요. 채원이가 가장 기억에 남는다고 한 장면은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X04']::text[],false,'{"seq":2,"concept":"K2-1-u8-C6","difficulty":2,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 채원이가 가장 기억에 남는다고 한 장면은 무엇인가요?","options":[{"t":"토토가 김밥을 내미는 장면","correct":true},{"t":"도시락이 텅 비어 있는 장면","mis":"K2-1-u8-X03"},{"t":"다미가 빵을 나누어 주는 장면","mis":"K2-1-u8-X04"}],"explanation":["채원이는 토토가 김밥을 내미는 장면을 골랐어요.","빈 도시락 장면은 채원이가 고른 장면이 아니에요.","빵을 나눈 다미의 장면도 아니에요."],"asset":{"type":"passage","lines":["저는 「보보의 빈 도시락」에서 토토가 김밥을 내미는 장면이 가장 기억에 남아요.","왜냐하면 혼자 있던 보보에게 먼저 다가간 토토가 멋졌기 때문이에요.","저도 전학 왔을 때 짝이 먼저 말을 걸어 줘서 정말 고마웠어요."],"title":"채원이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#3','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 「보보는 눈이 동그래졌다가 이내 활짝 웃었어요.」에서 보보의 마음은 어떻게 바뀌었나요?',ARRAY['K2-1-u8-X09','K2-1-u8-X05']::text[],false,'{"seq":3,"concept":"K2-1-u8-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「보보는 눈이 동그래졌다가 이내 활짝 웃었어요.」에서 보보의 마음은 어떻게 바뀌었나요?","options":[{"t":"놀랐다가 기뻐졌어요","correct":true},{"t":"기뻤다가 슬퍼졌어요","mis":"K2-1-u8-X09"},{"t":"화났다가 졸려졌어요","mis":"K2-1-u8-X05"}],"explanation":["눈이 동그래진 것은 놀람, 활짝 웃은 것은 기쁨이에요.","차례가 거꾸로 되었어요.","화나거나 졸린 마음은 보이지 않아요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#4','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',3,'error','auto','이야기를 읽고 인물의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 마음과 그렇게 짐작한 까닭을 말했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"도윤 — 「오빠는 연이 종이배가 뒤집혀서 고소했을 거야. 빙그레 웃었으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"지안 — 「오빠는 연이를 달래 주고 싶었을 거야. 괜찮다고 했으니까.」","mis":"K2-1-u8-X19"},{"t":"하준 — 「연이는 속상했을 거야. 발을 동동 굴렀으니까.」","mis":"K2-1-u8-X19"}],"explanation":["오빠는 괜찮다며 같이 다시 접자고 했으니 달래려고 웃은 거예요.","지안이와 하준이는 말과 행동에 맞게 짐작했어요.","말과 행동을 함께 살펴요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#5','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',3,'ox','auto','같은 이야기를 읽어도 친구마다 기억에 남는 장면이 다를 수 있어요.',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":5,"concept":"K2-1-u8-C6","difficulty":3,"kind":"ox","stem":"같은 이야기를 읽어도 친구마다 기억에 남는 장면이 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 느낀 점이 달라서","correct":true},{"t":"기억에 남는 장면은 모두 같아야 하니까","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["누구는 빈 도시락 장면이, 누구는 웃는 장면이 기억에 남을 수 있어요.","다른 장면을 고른 것은 틀린 것이 아니에요.","서로의 장면과 까닭을 들어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#6','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',3,'mc','auto','감상 발표를 읽고 답해 보세요. 채원이가 그 장면이 기억에 남는다고 한 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X04']::text[],false,'{"seq":6,"concept":"K2-1-u8-C6","difficulty":3,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 채원이가 그 장면이 기억에 남는다고 한 까닭은 무엇인가요?","options":[{"t":"혼자 있던 보보에게 먼저 다가간 토토가 멋졌기 때문에","correct":true},{"t":"당근 김밥이 맛있어 보였기 때문에","mis":"K2-1-u8-X03"},{"t":"다미가 빵을 반으로 나누었기 때문에","mis":"K2-1-u8-X04"}],"explanation":["채원이는 「왜냐하면」 뒤에 까닭을 말했어요.","김밥이 맛있어 보였다는 말은 없어요.","다미 이야기는 채원이의 까닭이 아니에요."],"asset":{"type":"passage","lines":["저는 「보보의 빈 도시락」에서 토토가 김밥을 내미는 장면이 가장 기억에 남아요.","왜냐하면 혼자 있던 보보에게 먼저 다가간 토토가 멋졌기 때문이에요.","저도 전학 왔을 때 짝이 먼저 말을 걸어 줘서 정말 고마웠어요."],"title":"채원이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#7','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',3,'mc','auto','이야기를 읽고 답해 보세요. 토토와 다미가 보보에게 음식을 나누어 준 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":7,"concept":"K2-1-u8-C5","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토토와 다미가 보보에게 음식을 나누어 준 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"혼자 시무룩한 보보가 걱정되어서","correct":true},{"t":"남은 음식을 버리고 싶어서","mis":"K2-1-u8-X05"},{"t":"보보를 놀리고 싶어서","mis":"K2-1-u8-X05"}],"explanation":["혼자 있는 보보를 보고 걱정되어 다가갔을 거예요.","버리려 했다면 「같이 먹자」고 하지 않았을 거예요.","놀리는 말이나 행동은 없어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#8','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',4,'mc','auto','이야기를 읽고 생각이나 느낌을 표현하는 방법에 대해 바르게 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X02','K2-1-u8-X10']::text[],false,'{"seq":8,"concept":"K2-1-u8-C6","difficulty":4,"kind":"mc","stem":"이야기를 읽고 생각이나 느낌을 표현하는 방법에 대해 바르게 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「글로 쓰기 어려우면 장면을 그림으로 그리고 느낌을 한 줄 덧붙여도 돼.」","correct":true},{"t":"민준 — 「감상은 꼭 긴 글로만 써야 해.」","mis":"K2-1-u8-X02"},{"t":"로아 — 「줄거리를 처음부터 끝까지 그대로 옮겨 쓰면 돼.」","mis":"K2-1-u8-X10"}],"explanation":["글·그림·말 등 여러 방법으로 표현할 수 있어요.","긴 글만 감상이 되는 것은 아니에요.","줄거리만 옮기면 내 느낌이 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#9','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',4,'essay','teacher','이야기를 읽고 답해 보세요. 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 오빠가 「같이 접어 보자.」라고 하는 장면이 가장 기억에 남아요. 왜냐하면 울상인 동생을 탓하지 않고 다정하게 도와준 오빠가 멋졌기 때문이에요. 저도 줄넘기가 안 될 때 언니가 같이 연습해 줘서 힘이 났던 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#10','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C5',4,'essay','teacher','이야기를 읽고 답해 보세요. 보보의 마음이 처음·가운데·끝에 어떻게 바뀌었는지 쓰고, 무엇 때문에 마음이 바뀌었는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 처음·가운데·끝에 어떻게 바뀌었는지 쓰고, 무엇 때문에 마음이 바뀌었는지 써 보세요.","answer_guide":{"answer":"예: 처음에는 도시락이 비어 있어 깜짝 놀랐고, 가운데에서는 혼자 나무 뒤에 앉아 시무룩했고, 끝에는 활짝 웃으며 고마워했어요. 토토와 다미가 음식을 나누어 주어서 마음이 바뀌었어요.","scoring_points":["처음·가운데·끝의 마음을 차례대로 썼는가","마음이 바뀐 까닭을 썼는가","이야기 속 말·행동과 맞게 썼는가"]},"explanation":["처음·가운데·끝 마음.","바뀐 까닭.","말·행동과 맞는지."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#1','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',1,'mc','auto','인형극에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u8-X01','K2-1-u8-X11']::text[],true,'{"seq":1,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"인형극에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"인형이 나와 말과 움직임으로 이야기를 보여 주는 극이에요","correct":true},{"t":"소리 내어 낭송하는 짧은 글이에요","mis":"K2-1-u8-X01"},{"t":"혼자 조용히 읽는 이야기책이에요","mis":"K2-1-u8-X11"}],"explanation":["인형극은 인형이 움직이며 이야기를 보여 줘요.","짧은 글을 낭송하는 것은 시예요.","인형극은 보고 들으며 감상해요."],"variant_rule":{"alt":[{"stem":"빛을 비추어 생긴 그림자로 이야기를 보여 주는 인형극은 어느 것인가요?","options":[{"t":"그림자 인형극","correct":true},{"t":"손가락 인형극","mis":"K2-1-u8-X11"},{"t":"막대 인형극","mis":"K2-1-u8-X11"}],"explanation":["빛과 그림자로 보여 주는 것이 그림자 인형극이에요.","손가락 인형극은 손가락에 인형을 끼워요.","막대 인형극은 막대에 붙인 인형을 움직여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#2','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',1,'mc','auto','인형극 대본을 읽고 답해 보세요. 오빠가 작은 목소리로 속삭인 것에서 알 수 있는 오빠의 마음은 어느 것인가요?',ARRAY['K2-1-u8-X12']::text[],true,'{"seq":2,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 오빠가 작은 목소리로 속삭인 것에서 알 수 있는 오빠의 마음은 어느 것인가요?","options":[{"t":"호랑이에게 들킬까 봐 조심스럽고 무섭다","correct":true},{"t":"신나고 즐겁다","mis":"K2-1-u8-X12"},{"t":"졸리고 심심하다","mis":"K2-1-u8-X12"}],"explanation":["속삭이는 작은 목소리에 들킬까 봐 조심하는 마음이 담겨 있어요.","신이 났다면 크고 빠르게 말했을 거예요.","졸린 마음은 이 장면과 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 흥부가 깜짝 놀라 커다란 목소리로 말한 것에서 알 수 있는 흥부의 마음은 어느 것인가요?","options":[{"t":"놀랍고 기쁘다","correct":true},{"t":"무섭고 슬프다","mis":"K2-1-u8-X12"},{"t":"지루하고 심심하다","mis":"K2-1-u8-X12"}],"explanation":["쌀이 쏟아져 놀라고 기뻐서 큰 목소리가 나왔어요.","무섭거나 슬픈 장면이 아니에요.","지루했다면 커다란 목소리가 나오지 않았을 거예요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#3','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',1,'ox','auto','인형극에서는 인물의 목소리 크기와 빠르기로도 마음을 짐작할 수 있어요.',ARRAY['K2-1-u8-X11']::text[],true,'{"seq":3,"concept":"K2-1-u8-C7","difficulty":1,"kind":"ox","stem":"인형극에서는 인물의 목소리 크기와 빠르기로도 마음을 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"신나면 크고 빠르게, 무서우면 작고 떨리게 말하니까","correct":true},{"t":"인형극에서 마음은 대사의 뜻으로만 알 수 있으니까","mis":"K2-1-u8-X11"}],"mis":"K2-1-u8-X11","explanation":["목소리에 인물의 마음이 묻어나요.","대사의 뜻과 함께 목소리·움직임도 살펴요.","말·행동·목소리를 모두 보고 들어요."],"variant_rule":{"alt":[{"stem":"인형극은 이야기책처럼 글만 읽으며 감상해요.","answer":"X","reason_options":[{"t":"인형의 움직임과 목소리를 보고 들으며 감상하니까","correct":true},{"t":"인형극에는 목소리와 움직임이 없으니까","mis":"K2-1-u8-X11"}],"explanation":["인형극은 눈과 귀로 함께 감상해요.","인형의 움직임과 목소리에 마음이 드러나요.","그래서 이야기책과 느낌이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#4','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',1,'mc','auto','줄거리를 읽고 답해 보세요. 엄마가 호랑이를 만난 곳은 어디인가요?',ARRAY['K2-1-u8-X13']::text[],true,'{"seq":4,"concept":"K2-1-u8-C8","difficulty":1,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 엄마가 호랑이를 만난 곳은 어디인가요?","options":[{"t":"고개","correct":true},{"t":"집","mis":"K2-1-u8-X13"},{"t":"나무 위","mis":"K2-1-u8-X13"}],"explanation":["떡을 팔고 고개를 넘어오다 호랑이를 만났어요.","집은 오누이가 기다리던 곳이에요.","나무 위는 오누이가 피한 곳이에요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"},"variant_rule":{"alt":[{"stem":"줄거리를 읽고 답해 보세요. 오누이가 호랑이를 피해 올라간 곳은 어디인가요?","options":[{"t":"우물가 나무 위","correct":true},{"t":"고개","mis":"K2-1-u8-X13"},{"t":"지붕 위","mis":"K2-1-u8-X03"}],"explanation":["오누이는 뒷문으로 나가 우물가 나무 위로 올라갔어요.","고개는 엄마가 호랑이를 만난 곳이에요.","지붕 위로 올라갔다는 말은 없어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#5','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',2,'match','auto','인형극의 종류와 그 특징을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극의 종류와 그 특징을 알맞게 이어 보세요.","pairs":[{"l":"그림자 인형극","r":"빛을 비추어 생긴 그림자로 보여 줘요"},{"l":"막대 인형극","r":"막대에 붙인 인형을 움직여요"},{"l":"손가락 인형극","r":"손가락에 인형을 끼워 움직여요"}],"mis":"K2-1-u8-X11","explanation":["그림자 인형극은 빛과 그림자를 써요.","막대 인형극은 막대로 인형을 움직여요.","손가락 인형극은 손가락에 인형을 끼워요."],"variant_rule":{"alt":[{"stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"작고 떨리는 목소리","r":"무섭다"},{"l":"크고 빠른 목소리","r":"신난다"},{"l":"느리고 힘없는 목소리","r":"슬프다"}],"explanation":["무서우면 목소리가 작고 떨려요.","신나면 크고 빨라져요.","슬프면 느리고 힘이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#6','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 누이가 떨리는 목소리로 말한 것에서 알 수 있는 누이의 마음은 어느 것인가요?',ARRAY['K2-1-u8-X12']::text[],true,'{"seq":6,"concept":"K2-1-u8-C7","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 누이가 떨리는 목소리로 말한 것에서 알 수 있는 누이의 마음은 어느 것인가요?","options":[{"t":"무섭고 겁이 난다","correct":true},{"t":"반갑고 기쁘다","mis":"K2-1-u8-X12"},{"t":"화가 나서 따지고 싶다","mis":"K2-1-u8-X12"}],"explanation":["떨리는 목소리에 무서운 마음이 담겨 있어요.","엄마인지 의심하는 장면이라 반가운 마음이 아니에요.","화난 목소리라면 떨리지 않고 커졌을 거예요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 흥부 아내가 노래하듯 흥겹게 말한 것에서 알 수 있는 마음은 어느 것인가요?","options":[{"t":"박에서 무엇이 나올지 설레고 즐겁다","correct":true},{"t":"무섭고 걱정된다","mis":"K2-1-u8-X12"},{"t":"슬프고 서운하다","mis":"K2-1-u8-X12"}],"explanation":["흥겨운 노랫소리에 설레는 마음이 담겨 있어요.","무서웠다면 흥겹게 노래하지 않았을 거예요.","슬픈 마음은 이 장면과 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#7','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],true,'{"seq":7,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"집 → 고개 → 집 → 나무 위 → 하늘","correct":true},{"t":"고개 → 나무 위 → 집 → 하늘","mis":"K2-1-u8-X13"},{"t":"집 → 나무 위 → 고개 → 하늘","mis":"K2-1-u8-X13"}],"explanation":["엄마가 집을 나서 고개에서 호랑이를 만나고, 호랑이가 집으로 온 뒤 오누이는 나무 위를 거쳐 하늘로 올라갔어요.","나무 위는 호랑이가 집에 온 다음이에요.","고개는 나무 위보다 먼저예요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"박이 열린다 → 박을 탄다 → 쌀이 쏟아진다 → 아이들이 기뻐한다","correct":true},{"t":"쌀이 쏟아진다 → 박이 열린다 → 박을 탄다 → 아이들이 기뻐한다","mis":"K2-1-u8-X13"},{"t":"박을 탄다 → 아이들이 기뻐한다 → 박이 열린다 → 쌀이 쏟아진다","mis":"K2-1-u8-X13"}],"explanation":["박이 열리고, 박을 타자, 쌀이 쏟아졌고, 아이들이 기뻐했어요.","박이 열리기 전에 쌀이 쏟아질 수 없어요.","박을 타기 전에 박이 먼저 열려야 해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#8','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C7',2,'error','auto','인형극 대본을 읽고 인물의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C7","difficulty":2,"kind":"error","stem":"인형극 대본을 읽고 인물의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"서준 — 「오빠는 신이 났을 거야. 누이 손을 꼭 잡았으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"하윤 — 「누이는 무서웠을 거야. 목소리가 떨렸으니까.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「오빠는 누이를 지키고 싶었을 거야. 손을 꼭 잡고 뒷문으로 나갔으니까.」","mis":"K2-1-u8-X19"}],"explanation":["호랑이를 피해 달아나는 장면이라 신이 났을 리 없어요.","하윤이와 윤호는 목소리와 행동에 맞게 짐작했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 인형극 대본을 읽고 인물의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"지호 — 「아이들은 슬펐을 거야. 깡충깡충 뛰었으니까.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"채원 — 「흥부는 놀랐을 거야. 커다란 목소리로 말했으니까.」","mis":"K2-1-u8-X19"},{"t":"다은 — 「흥부 아내는 즐거웠을 거야. 노래하듯 흥겹게 말했으니까.」","mis":"K2-1-u8-X19"}],"explanation":["깡충깡충 뛰며 「배불리 먹을 수 있다!」고 했으니 기뻤어요.","채원이와 다은이는 목소리에 맞게 짐작했어요.","물음의 「잘못」에 동그라미를 쳐요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#9','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',2,'sa','auto','줄거리를 읽고 답해 보세요. 오누이가 잡고 하늘로 올라간 것을 세 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C8","difficulty":2,"kind":"sa","stem":"줄거리를 읽고 답해 보세요. 오누이가 잡고 하늘로 올라간 것을 세 글자로 써 보세요.","answer":["동아줄"],"explanation":["하늘에서 내려온 튼튼한 동아줄을 잡았어요.","오누이는 하늘로 올라가 해와 달이 되었어요.","줄거리에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"},"variant_rule":{"alt":[{"stem":"줄거리를 읽고 답해 보세요. 엄마가 집을 나서 팔러 간 것을 한 글자로 써 보세요.","answer":["떡"],"explanation":["엄마는 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오다 호랑이를 만났어요.","줄거리에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#10','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C8',3,'mc','auto','장소가 바뀔 때마다 일어난 일을 나누어 정리하면 좋은 점은 무엇인가요?',ARRAY['K2-1-u8-X13','K2-1-u8-X02']::text[],true,'{"seq":10,"concept":"K2-1-u8-C8","difficulty":3,"kind":"mc","stem":"장소가 바뀔 때마다 일어난 일을 나누어 정리하면 좋은 점은 무엇인가요?","options":[{"t":"일이 일어난 차례와 줄거리를 한눈에 알 수 있어요","correct":true},{"t":"인물의 이름을 바꿀 수 있어요","mis":"K2-1-u8-X13"},{"t":"작품을 끝까지 보지 않아도 돼요","mis":"K2-1-u8-X02"}],"explanation":["장소마다 일어난 일을 정리하면 줄거리가 보여요.","이름을 바꾸는 것과는 상관없어요.","작품은 끝까지 감상해야 해요."],"variant_rule":{"alt":[{"stem":"줄거리를 읽고 답해 보세요. 「호랑이가 오누이가 기다리는 집으로 찾아갔어요.」 바로 다음에 일어난 일은 무엇인가요?","options":[{"t":"오누이가 뒷문으로 빠져나가 나무 위로 올라갔어요","correct":true},{"t":"엄마가 고개에서 호랑이를 만났어요","mis":"K2-1-u8-X13"},{"t":"오누이가 해와 달이 되었어요","mis":"K2-1-u8-X13"}],"explanation":["호랑이가 집에 오자 오누이는 나무 위로 피했어요.","엄마가 호랑이를 만난 일은 그보다 앞이에요.","해와 달이 된 것은 맨 마지막이에요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#1','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',2,'mc','auto','인형극과 이야기책의 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":1,"concept":"K2-1-u8-C7","difficulty":2,"kind":"mc","stem":"인형극과 이야기책의 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"인형극은 인물의 움직임과 목소리를 직접 보고 들을 수 있어요","correct":true},{"t":"인형극에는 인물이 나오지 않아요","mis":"K2-1-u8-X11"},{"t":"인형극에는 이야기가 없어요","mis":"K2-1-u8-X11"}],"explanation":["인형극은 움직임과 목소리로 이야기를 보여 줘요.","인형극에도 인물이 나와요.","인형극도 이야기를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#2','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 엄마가 집을 나서며 오누이에게 이른 것은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X04']::text[],false,'{"seq":2,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 엄마가 집을 나서며 오누이에게 이른 것은 무엇인가요?","options":[{"t":"문을 꼭 잠그라고","correct":true},{"t":"나무 위로 올라가라고","mis":"K2-1-u8-X03"},{"t":"떡을 팔아 오라고","mis":"K2-1-u8-X04"}],"explanation":["엄마는 문을 꼭 잠그라고 일렀어요.","나무에 올라가라는 말은 없어요.","떡을 팔러 간 것은 엄마예요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#3','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 호랑이가 굵고 느린 목소리로 말하자 오빠가 알아챈 것은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":3,"concept":"K2-1-u8-C7","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 호랑이가 굵고 느린 목소리로 말하자 오빠가 알아챈 것은 무엇인가요?","options":[{"t":"엄마 목소리와 다르다는 것","correct":true},{"t":"엄마가 감기에 걸렸다는 것","mis":"K2-1-u8-X03"},{"t":"누이가 문을 열었다는 것","mis":"K2-1-u8-X03"}],"explanation":["오빠는 「목소리가 엄마랑 달라.」라고 했어요.","감기에 걸렸다는 말은 없어요.","누이는 문을 열지 않고 손을 보여 달라고 했어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#4','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',3,'error','auto','줄거리를 읽고 일이 일어난 차례를 말했어요. 차례를 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X13','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C8","difficulty":3,"kind":"error","stem":"줄거리를 읽고 일이 일어난 차례를 말했어요. 차례를 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「오누이가 하늘로 올라간 뒤에 호랑이가 집에 찾아왔어.」","correct":true,"mis_target":"K2-1-u8-X13"},{"t":"민준 — 「엄마가 고개에서 호랑이를 만난 뒤에 호랑이가 집에 찾아왔어.」","mis":"K2-1-u8-X19"},{"t":"소율 — 「오누이는 나무 위로 올라간 뒤에 동아줄을 잡았어.」","mis":"K2-1-u8-X19"}],"explanation":["호랑이가 집에 온 뒤에 오누이가 나무 위를 거쳐 하늘로 올라갔어요.","민준이와 소율이는 차례를 바르게 말했어요.","장소가 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#5','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',3,'ox','auto','같은 대사라도 목소리의 크기와 빠르기를 바꾸면 전해지는 마음이 달라져요.',ARRAY['K2-1-u8-X12']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":3,"kind":"ox","stem":"같은 대사라도 목소리의 크기와 빠르기를 바꾸면 전해지는 마음이 달라져요.","answer":"O","reason_options":[{"t":"「문 열어라.」도 굵고 느리게 하면 무섭게, 작고 부드럽게 하면 다정하게 들리니까","correct":true},{"t":"대사가 같으면 전해지는 마음도 언제나 같으니까","mis":"K2-1-u8-X12"}],"mis":"K2-1-u8-X12","explanation":["목소리에 따라 같은 말도 다르게 들려요.","그래서 인형극에서는 목소리를 잘 들어야 해요.","직접 두 가지 목소리로 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#6','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 오빠가 누이 손을 꼭 잡고 뒷문으로 살금살금 나간 행동에서 알 수 있는 오빠의 마음은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":6,"concept":"K2-1-u8-C7","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 오빠가 누이 손을 꼭 잡고 뒷문으로 살금살금 나간 행동에서 알 수 있는 오빠의 마음은 어느 것인가요?","options":[{"t":"동생을 지키며 무사히 달아나고 싶은 마음","correct":true},{"t":"동생과 장난치고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"호랑이와 친해지고 싶은 마음","mis":"K2-1-u8-X05"}],"explanation":["손을 꼭 잡고 몰래 나간 행동에 동생을 지키려는 마음이 보여요.","장난치는 장면이 아니에요.","호랑이를 피해 달아나는 장면이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#7','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',3,'mc','auto','줄거리를 읽고 답해 보세요. 장소가 「집」일 때 일어난 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":7,"concept":"K2-1-u8-C8","difficulty":3,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 장소가 「집」일 때 일어난 일로 알맞은 것은 어느 것인가요?","options":[{"t":"호랑이가 엄마 옷을 입고 찾아왔어요","correct":true},{"t":"엄마가 떡을 팔고 오다 호랑이를 처음 만났어요","mis":"K2-1-u8-X13"},{"t":"오누이가 동아줄을 잡았어요","mis":"K2-1-u8-X13"}],"explanation":["호랑이는 엄마 옷을 입고 집으로 찾아왔어요.","호랑이를 처음 만난 곳은 고개예요.","동아줄은 나무 위에서 잡았어요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#8','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',4,'mc','auto','인형극 대본을 읽고 답해 보세요. 「얘들아, 엄마 왔다. 문 열어라.」를 엄마인 척 속이려는 호랑이의 마음이 드러나게 연기하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X11']::text[],false,'{"seq":8,"concept":"K2-1-u8-C7","difficulty":4,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 「얘들아, 엄마 왔다. 문 열어라.」를 엄마인 척 속이려는 호랑이의 마음이 드러나게 연기하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"엄마 목소리를 흉내 내 부드럽게 말하면서 인형을 문 쪽으로 슬금슬금 다가가게 하기","correct":true},{"t":"울먹이는 목소리로 말하며 인형을 바닥에 눕히기","mis":"K2-1-u8-X12"},{"t":"아무 움직임 없이 대사만 빠르게 읽기","mis":"K2-1-u8-X11"}],"explanation":["속이려는 마음은 꾸민 목소리와 슬금슬금 다가가는 움직임으로 살아나요.","울먹이는 목소리는 속이려는 마음과 맞지 않아요.","움직임 없이 빠르게 읽으면 마음이 드러나지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#9','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 오빠와 누이 가운데 한 인물을 골라 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 오빠와 누이 가운데 한 인물을 골라 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 누이는 무척 무서웠을 거예요. 왜냐하면 떨리는 목소리로 말했고, 문을 열기 전에 손을 먼저 보여 달라고 할 만큼 의심스러웠기 때문이에요.","scoring_points":["한 인물을 골라 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#10','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C8',4,'essay','teacher','줄거리를 읽고 답해 보세요. 장소가 바뀔 때마다 일어난 일을 차례대로 정리해 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C8","difficulty":4,"kind":"essay","stem":"줄거리를 읽고 답해 보세요. 장소가 바뀔 때마다 일어난 일을 차례대로 정리해 써 보세요.","answer_guide":{"answer":"예: 집 — 엄마가 떡을 팔러 나섰어요. 고개 — 엄마가 호랑이를 만났어요. 집 — 호랑이가 엄마 옷을 입고 찾아왔어요. 나무 위 — 오누이가 호랑이를 피해 올라갔어요. 하늘 — 동아줄을 잡고 올라가 해와 달이 되었어요.","scoring_points":["장소를 차례대로 썼는가","장소마다 일어난 일을 썼는가","줄거리와 다른 내용을 넣지 않았는가"]},"explanation":["장소의 차례.","장소마다 일어난 일.","줄거리와 같은지."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#1','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',1,'mc','auto','인형극 대본을 읽고 답해 보세요. 형이 밤에 몰래 볏단을 옮긴 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],true,'{"seq":1,"concept":"K2-1-u8-C9","difficulty":1,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형이 밤에 몰래 볏단을 옮긴 까닭은 무엇인가요?","options":[{"t":"아우가 살림을 막 차려서 쌀이 더 필요할 것 같아서","correct":true},{"t":"볏단이 너무 무거워 치우고 싶어서","mis":"K2-1-u8-X03"},{"t":"아우를 골탕 먹이고 싶어서","mis":"K2-1-u8-X05"}],"explanation":["형은 「아우는 살림을 막 차려서 쌀이 더 필요할 거야.」라고 했어요.","볏단이 무거워 치우려 했다는 말은 없어요.","아우를 생각해서 한 일이지 골탕 먹이려던 것이 아니에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 아우가 밤에 몰래 볏단을 옮긴 까닭은 무엇인가요?","options":[{"t":"형님은 식구가 많아서 볏단이 더 있어야 할 것 같아서","correct":true},{"t":"형님 볏단을 빼앗고 싶어서","mis":"K2-1-u8-X05"},{"t":"잠이 오지 않아 심심해서","mis":"K2-1-u8-X03"}],"explanation":["아우는 「형님은 식구가 많으니 볏단이 더 있어야 해.」라고 했어요.","아우는 볏단을 빼앗은 것이 아니라 가져다주었어요.","심심했다는 말은 없어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#2','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',1,'mc','auto','작품 속 인물에게 쓰는 편지에 꼭 담으면 좋은 것은 무엇인가요?',ARRAY['K2-1-u8-X14']::text[],true,'{"seq":2,"concept":"K2-1-u8-C10","difficulty":1,"kind":"mc","stem":"작품 속 인물에게 쓰는 편지에 꼭 담으면 좋은 것은 무엇인가요?","options":[{"t":"인물에게 하고 싶은 말과 그 까닭","correct":true},{"t":"내 생일 날짜","mis":"K2-1-u8-X14"},{"t":"작품의 글자 수","mis":"K2-1-u8-X14"}],"explanation":["하고 싶은 말과 까닭을 담으면 내 생각과 느낌이 잘 전해져요.","생일 날짜는 인물에게 할 말과 상관없어요.","글자 수도 상관없어요."],"variant_rule":{"alt":[{"stem":"인물에게 쓴 편지 첫 줄에 「형님께」라고 썼어요. 이 부분은 무엇을 나타내나요?","options":[{"t":"편지를 받는 인물","correct":true},{"t":"편지를 쓴 사람","mis":"K2-1-u8-X14"},{"t":"편지를 쓴 날의 날씨","mis":"K2-1-u8-X14"}],"explanation":["「형님께」는 편지를 받는 인물이에요.","쓴 사람은 편지 끝에 밝혀요.","날씨를 나타낸 말이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#3','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',1,'ox','auto','인형극 대본을 읽고 답해 보세요. 형과 아우는 볏단을 옮기기 전에 서로에게 미리 알렸어요.',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":3,"concept":"K2-1-u8-C9","difficulty":1,"kind":"ox","stem":"인형극 대본을 읽고 답해 보세요. 형과 아우는 볏단을 옮기기 전에 서로에게 미리 알렸어요.","answer":"X","reason_options":[{"t":"둘 다 몰래 집을 나서서 볏단을 옮겼다고 했으니까","correct":true},{"t":"둘이 함께 의논해서 옮겼으니까","mis":"K2-1-u8-X03"}],"mis":"K2-1-u8-X03","explanation":["형은 살금살금, 아우는 몰래 볏단을 옮겼어요.","그래서 다음 날 볏단이 줄지 않아 둘 다 놀랐어요.","대본에서 「몰래」를 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 형과 아우는 달밤에 마주쳐 서로의 마음을 알게 되었어요.","answer":"O","reason_options":[{"t":"형이 「네가 나를 생각해 주었구나.」라고 했으니까","correct":true},{"t":"두 사람은 끝까지 서로의 마음을 몰랐으니까","mis":"K2-1-u8-X03"}],"explanation":["달밤에 마주쳐 서로를 위해 볏단을 옮긴 것을 알았어요.","형은 아우를 꼭 안았어요.","대본에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#4','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C11',1,'mc','auto','감상을 발표할 때의 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],true,'{"seq":4,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"감상을 발표할 때의 바른 자세는 어느 것인가요?","options":[{"t":"또박또박 말하고 왜 그렇게 생각했는지 까닭도 함께 말해요","correct":true},{"t":"작은 목소리로 웅얼웅얼 말해요","mis":"K2-1-u8-X15"},{"t":"바닥만 보며 빨리 끝내요","mis":"K2-1-u8-X15"}],"explanation":["또박또박 까닭과 함께 말하면 감상이 잘 전해져요.","웅얼거리면 친구들이 듣기 어려워요.","바닥만 보면 마음이 잘 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"친구의 감상 발표를 들을 때의 바른 자세는 어느 것인가요?","options":[{"t":"좋은 점을 찾으며 끝까지 들어요","correct":true},{"t":"나와 다르면 틀렸다고 말해요","mis":"K2-1-u8-X15"},{"t":"짝과 다른 이야기를 해요","mis":"K2-1-u8-X15"}],"explanation":["좋은 점을 찾으며 들으면 감상이 넓어져요.","나와 다른 감상도 틀린 것이 아니에요.","딴 이야기를 하면 발표를 들을 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#5','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',2,'match','auto','편지를 읽고 편지의 부분과 그 부분이 나타내는 것을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C10","difficulty":2,"kind":"match","stem":"편지를 읽고 편지의 부분과 그 부분이 나타내는 것을 알맞게 이어 보세요.","pairs":[{"l":"형님께","r":"받는 인물"},{"l":"형님처럼 동생을 먼저 생각해 볼게요","r":"하고 싶은 말"},{"l":"2학년 하준 올림","r":"쓴 사람"}],"mis":"K2-1-u8-X14","explanation":["「형님께」는 받는 인물이에요.","다짐하는 말은 하준이가 하고 싶은 말이에요.","「하준 올림」은 쓴 사람이에요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 편지를 읽고 편지의 부분과 그 부분이 나타내는 것을 알맞게 이어 보세요.","pairs":[{"l":"보보에게","r":"받는 인물"},{"l":"다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라","r":"하고 싶은 말"},{"l":"서윤이가","r":"쓴 사람"}],"explanation":["「보보에게」는 받는 인물이에요.","바라는 말은 서윤이가 하고 싶은 말이에요.","「서윤이가」는 쓴 사람이에요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#6','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 다음 날 아침 형과 아우가 고개를 갸웃한 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":6,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 다음 날 아침 형과 아우가 고개를 갸웃한 까닭은 무엇인가요?","options":[{"t":"볏단이 하나도 줄지 않아서","correct":true},{"t":"볏단이 모두 없어져서","mis":"K2-1-u8-X03"},{"t":"밤새 비가 와서","mis":"K2-1-u8-X03"}],"explanation":["서로 옮겼는데도 볏단이 줄지 않아 이상했어요.","볏단이 없어진 것이 아니라 그대로였어요.","비가 왔다는 말은 없어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 형이 볏단을 내려놓고 아우를 꼭 안은 까닭은 무엇인가요?","options":[{"t":"아우도 자기를 생각해 주었다는 것을 알게 되어서","correct":true},{"t":"볏단이 무거워서","mis":"K2-1-u8-X06"},{"t":"아우가 볏단을 훔쳐 가서","mis":"K2-1-u8-X05"}],"explanation":["형은 「네가 나를 생각해 주었구나.」라고 했어요.","볏단이 무거운 것은 아우를 안은 까닭이 아니에요.","아우는 훔친 것이 아니라 가져다주었어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#7','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 하준이가 형에게 다짐한 것은 무엇인가요?',ARRAY['K2-1-u8-X03']::text[],true,'{"seq":7,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 하준이가 형에게 다짐한 것은 무엇인가요?","options":[{"t":"형님처럼 동생을 먼저 생각하겠다","correct":true},{"t":"밤마다 볏단을 옮기겠다","mis":"K2-1-u8-X03"},{"t":"새 장난감을 사겠다","mis":"K2-1-u8-X03"}],"explanation":["하준이는 「형님처럼 동생을 먼저 생각해 볼게요.」라고 했어요.","볏단을 옮기겠다는 말은 없어요.","장난감을 사겠다는 말도 없어요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"},"variant_rule":{"alt":[{"stem":"편지를 읽고 답해 보세요. 서윤이가 보보에게 바란 것은 무엇인가요?","options":[{"t":"다음 소풍에는 맛있는 도시락을 싸 가기를","correct":true},{"t":"토토와 다투지 않기를","mis":"K2-1-u8-X03"},{"t":"혼자 소풍을 가기를","mis":"K2-1-u8-X03"}],"explanation":["서윤이는 맛있는 도시락을 싸 가길 바랐어요.","토토와 다투었다는 내용은 없어요.","혼자 가라는 말은 없어요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#8','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C11',2,'error','auto','친구의 감상 발표를 듣고 한 말이에요. 바르지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u8-X15','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C11","difficulty":2,"kind":"error","stem":"친구의 감상 발표를 듣고 한 말이에요. 바르지 않게 말한 친구는 누구인가요?","options":[{"t":"하람 — 「나는 다른 장면이 좋았으니까 네 감상은 틀렸어.」","correct":true,"mis_target":"K2-1-u8-X15"},{"t":"아린 — 「네 까닭을 들으니 나도 그 장면이 다시 떠올라.」","mis":"K2-1-u8-X19"},{"t":"지우 — 「나와 고른 장면은 다르지만 형제를 아끼는 마음에 감동한 점은 비슷하네.」","mis":"K2-1-u8-X19"}],"explanation":["나와 다른 감상도 틀린 것이 아니에요.","아린이와 지우는 좋은 점을 찾고 견주어 들었어요.","물음의 「바르지 않게」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"감상을 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"태민 — 친구들에게 등을 돌리고 작게 웅얼거렸어요","correct":true,"mis_target":"K2-1-u8-X15"},{"t":"하린 — 친구들을 바라보며 또박또박 말했어요","mis":"K2-1-u8-X19"},{"t":"건우 — 기억에 남는 장면과 까닭을 함께 말했어요","mis":"K2-1-u8-X19"}],"explanation":["등을 돌리고 웅얼거리면 감상이 전해지지 않아요.","하린이와 건우는 바르게 발표했어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#9','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C9',2,'sa','auto','인형극 대본을 읽고 답해 보세요. 형과 아우가 밤마다 몰래 옮긴 것을 두 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C9","difficulty":2,"kind":"sa","stem":"인형극 대본을 읽고 답해 보세요. 형과 아우가 밤마다 몰래 옮긴 것을 두 글자로 써 보세요.","answer":["볏단"],"explanation":["형과 아우는 볏단을 지고 몰래 옮겼어요.","서로를 위해 옮겼어요.","대본에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]},"variant_rule":{"alt":[{"stem":"인형극 대본을 읽고 답해 보세요. 형과 아우가 마주친 날 밤하늘에 떠 있던 것을 한 글자로 써 보세요.","answer":["달"],"explanation":["사흘째 밤 하늘에 둥근 달이 떴어요.","달밤에 두 사람이 마주쳤어요.","대본에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#10','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C10',3,'mc','auto','「의좋은 형제」의 인물에게 쓴 편지예요. 받는 인물·하고 싶은 말·까닭이 가장 잘 드러나게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u8-X14']::text[],true,'{"seq":10,"concept":"K2-1-u8-C10","difficulty":3,"kind":"mc","stem":"「의좋은 형제」의 인물에게 쓴 편지예요. 받는 인물·하고 싶은 말·까닭이 가장 잘 드러나게 쓴 것은 어느 것인가요?","options":[{"t":"「아우님께, 형님을 위해 몰래 볏단을 옮긴 마음이 멋져요. 저도 언니를 먼저 생각하는 동생이 될게요.」","correct":true},{"t":"「아우님께, 안녕. 잘 지내.」","mis":"K2-1-u8-X14"},{"t":"「엄마께, 오늘 저녁 반찬은 뭐예요?」","mis":"K2-1-u8-X14"}],"explanation":["받는 인물·하고 싶은 말·까닭이 모두 들어 있어요.","인사만 있고 하고 싶은 말과 까닭이 없어요.","작품 속 인물에게 쓴 편지가 아니에요."],"variant_rule":{"alt":[{"stem":"「보보의 빈 도시락」의 인물에게 쓴 편지예요. 받는 인물·하고 싶은 말·까닭이 가장 잘 드러나게 쓴 것은 어느 것인가요?","options":[{"t":"「토토에게, 혼자 있던 보보에게 먼저 다가가 줘서 멋졌어. 나도 외로운 친구에게 먼저 말을 걸어 볼게.」","correct":true},{"t":"「토토에게, 토토는 토끼구나.」","mis":"K2-1-u8-X14"},{"t":"「짝에게, 내일 같이 놀자.」","mis":"K2-1-u8-X14"}],"explanation":["받는 인물·하고 싶은 말·까닭이 모두 들어 있어요.","하고 싶은 말과 까닭이 없어요.","작품 속 인물에게 쓴 편지가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#1','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C9',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 형이 「아니, 저기 오는 사람은……?」 하고 멈칫할 때의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":1,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형이 「아니, 저기 오는 사람은……?」 하고 멈칫할 때의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구일까 궁금하고 놀랍다","correct":true},{"t":"신나고 즐겁다","mis":"K2-1-u8-X05"},{"t":"졸리고 지루하다","mis":"K2-1-u8-X05"}],"explanation":["어두운 밤 누군가 다가오니 궁금하고 놀랐을 거예요.","멈칫하는 행동에서 신나는 마음은 보이지 않아요.","졸린 마음은 이 장면과 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#2','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',2,'mc','auto','감상 발표를 읽고 답해 보세요. 민준이가 가장 기억에 남는다고 한 장면은 무엇인가요?',ARRAY['K2-1-u8-X10']::text[],false,'{"seq":2,"concept":"K2-1-u8-C11","difficulty":2,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 민준이가 가장 기억에 남는다고 한 장면은 무엇인가요?","options":[{"t":"달밤에 형과 아우가 마주치는 장면","correct":true},{"t":"볏단이 줄지 않아 고개를 갸웃하는 장면","mis":"K2-1-u8-X10"},{"t":"형이 혼자 볏단을 지고 가는 장면","mis":"K2-1-u8-X10"}],"explanation":["민준이는 달밤에 마주치는 장면을 골랐어요.","고개를 갸웃하는 장면은 민준이가 고른 장면이 아니에요.","형이 혼자 가는 장면도 아니에요."],"asset":{"type":"passage","lines":["저는 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면이 가장 기억에 남아요.","서로를 위해 몰래 볏단을 옮긴 것을 알게 되어 가슴이 찡했기 때문이에요.","저도 언니가 몰래 제 준비물을 챙겨 준 것을 알고 뭉클했던 적이 있어요."],"title":"민준이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#3','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":3,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 옮긴 만큼 아우도 형에게 볏단을 옮겼기 때문에","correct":true},{"t":"볏단이 저절로 늘어났기 때문에","mis":"K2-1-u8-X03"},{"t":"이웃이 볏단을 가져다 놓았기 때문에","mis":"K2-1-u8-X03"}],"explanation":["두 사람이 서로에게 옮겨서 볏단 수가 그대로였어요.","볏단이 저절로 늘어나지는 않아요.","이웃 이야기는 대본에 없어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#4','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C10',3,'error','auto','「의좋은 형제」의 형에게 편지를 썼어요. 작품 내용과 맞지 않게 쓴 친구는 누구인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C10","difficulty":3,"kind":"error","stem":"「의좋은 형제」의 형에게 편지를 썼어요. 작품 내용과 맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"도담 — 「형님, 아우의 볏단을 몰래 빼앗아 가서 실망했어요.」","correct":true,"mis_target":"K2-1-u8-X03"},{"t":"서아 — 「형님, 식구가 많아 힘드실 텐데 아우를 먼저 생각하셔서 놀라웠어요.」","mis":"K2-1-u8-X19"},{"t":"준우 — 「형님, 달밤에 아우를 꼭 안아 주는 장면에서 저도 따뜻해졌어요.」","mis":"K2-1-u8-X19"}],"explanation":["형은 볏단을 빼앗지 않고 아우에게 가져다주었어요.","서아와 준우는 작품 내용에 맞게 썼어요.","작품에서 형이 한 일을 다시 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#5','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',3,'ox','auto','친구의 감상이 나와 다르면 견주어 들으며 비슷한 점과 다른 점을 찾아요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":5,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구의 감상이 나와 다르면 견주어 들으며 비슷한 점과 다른 점을 찾아요.","answer":"O","reason_options":[{"t":"견주어 들으면 작품을 더 넓고 깊게 감상할 수 있으니까","correct":true},{"t":"나와 다른 감상은 들을 필요가 없으니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["친구의 감상에서 내가 못 본 점을 발견할 수 있어요.","다른 감상도 존중하며 들어요.","비슷한 점·다른 점을 찾아 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#6','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',3,'mc','auto','감상 발표를 읽고 답해 보세요. 민준이가 말한 「비슷한 내 경험」에 해당하는 것은 어느 것인가요?',ARRAY['K2-1-u8-X10']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":3,"kind":"mc","stem":"감상 발표를 읽고 답해 보세요. 민준이가 말한 「비슷한 내 경험」에 해당하는 것은 어느 것인가요?","options":[{"t":"언니가 몰래 준비물을 챙겨 준 것을 알고 뭉클했던 일","correct":true},{"t":"달밤에 형과 아우가 마주친 일","mis":"K2-1-u8-X10"},{"t":"서로를 위해 볏단을 옮긴 것을 알게 된 일","mis":"K2-1-u8-X10"}],"explanation":["민준이는 마지막 문장에서 자기 경험을 말했어요.","달밤에 마주친 것은 작품 속 장면이에요.","볏단을 옮긴 것도 작품 속 일이에요."],"asset":{"type":"passage","lines":["저는 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면이 가장 기억에 남아요.","서로를 위해 몰래 볏단을 옮긴 것을 알게 되어 가슴이 찡했기 때문이에요.","저도 언니가 몰래 제 준비물을 챙겨 준 것을 알고 뭉클했던 적이 있어요."],"title":"민준이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#7','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C10',3,'mc','auto','인물에게 편지를 쓸 때 가장 중요하게 생각해야 할 것은 무엇인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":7,"concept":"K2-1-u8-C10","difficulty":3,"kind":"mc","stem":"인물에게 편지를 쓸 때 가장 중요하게 생각해야 할 것은 무엇인가요?","options":[{"t":"인물에게 하고 싶은 말을 솔직한 내 마음으로 담는 것","correct":true},{"t":"날짜를 맨 위에 꼭 크게 쓰는 것","mis":"K2-1-u8-X14"},{"t":"편지지를 예쁘게 꾸미는 것","mis":"K2-1-u8-X14"}],"explanation":["편지는 인물에게 내 마음을 전하는 감상 활동이에요.","형식보다 마음을 담는 것이 더 중요해요.","꾸미기보다 하고 싶은 말이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#8','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',4,'mc','auto','채원이는 「보보의 빈 도시락」에서 토토가 먼저 다가간 장면을, 민준이는 「의좋은 형제」에서 형제가 마주친 장면을 골랐어요. 두 감상을 견주어 볼 때 비슷한 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X10']::text[],false,'{"seq":8,"concept":"K2-1-u8-C11","difficulty":4,"kind":"mc","stem":"채원이는 「보보의 빈 도시락」에서 토토가 먼저 다가간 장면을, 민준이는 「의좋은 형제」에서 형제가 마주친 장면을 골랐어요. 두 감상을 견주어 볼 때 비슷한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 다른 이를 먼저 생각하는 인물의 마음에 감동했어요","correct":true},{"t":"둘 다 같은 작품을 골랐어요","mis":"K2-1-u8-X03"},{"t":"둘 다 까닭을 말하지 않았어요","mis":"K2-1-u8-X10"}],"explanation":["토토와 형제 모두 남을 먼저 생각했고, 두 친구는 그 마음에 감동했어요.","두 친구는 서로 다른 작품을 골랐어요.","두 친구 모두 까닭을 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#9','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C10',4,'essay','teacher','「의좋은 형제」의 형이나 아우 가운데 한 인물에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「의좋은 형제」의 형이나 아우 가운데 한 인물에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 아우님께 — 아우님, 식구가 많은 형님을 걱정해서 밤마다 볏단을 옮긴 마음이 정말 멋졌어요. 저는 동생과 간식을 나눌 때 큰 쪽을 먼저 집었거든요. 이제는 아우님처럼 동생 몫을 먼저 챙길게요. — 2학년 은솔 올림","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#10','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',4,'essay','teacher','감상 발표를 읽고 답해 보세요. 민준이의 감상과 내 감상을 견주어 비슷한 점과 다른 점을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C11","difficulty":4,"kind":"essay","stem":"감상 발표를 읽고 답해 보세요. 민준이의 감상과 내 감상을 견주어 비슷한 점과 다른 점을 써 보세요.","answer_guide":{"answer":"예: 민준이는 형제가 마주치는 장면이 기억에 남는다고 했고, 저는 볏단이 줄지 않아 고개를 갸웃하는 장면이 기억에 남아요. 고른 장면은 다르지만 서로를 아끼는 형제의 마음에 감동한 점은 비슷해요.","scoring_points":["민준이의 감상을 바르게 옮겼는가","내 감상을 썼는가","비슷한 점과 다른 점을 모두 썼는가"]},"explanation":["민준이의 감상.","내 감상.","비슷한 점·다른 점."],"asset":{"type":"passage","lines":["저는 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면이 가장 기억에 남아요.","서로를 위해 몰래 볏단을 옮긴 것을 알게 되어 가슴이 찡했기 때문이에요.","저도 언니가 몰래 제 준비물을 챙겨 준 것을 알고 뭉클했던 적이 있어요."],"title":"민준이의 감상 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#1','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'mc','auto','막대 인형을 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K2-1-u8-X16']::text[],true,'{"seq":1,"concept":"K2-1-u8-C12","difficulty":1,"kind":"mc","stem":"막대 인형을 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"맡은 인물을 두꺼운 종이에 그려요","correct":true},{"t":"인형에 막대를 붙여요","mis":"K2-1-u8-X16"},{"t":"친구들 앞에서 공연해요","mis":"K2-1-u8-X16"}],"explanation":["먼저 인물을 그려야 오리고 막대를 붙일 수 있어요.","막대는 그리고 오린 다음에 붙여요.","공연은 인형을 다 만든 뒤에 해요."],"variant_rule":{"alt":[{"stem":"막대 인형 만드는 차례예요. 「인물 그리기 → 오리기 → (   )」 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"막대 붙이기","correct":true},{"t":"표 사기","mis":"K2-1-u8-X16"},{"t":"공연 끝내기","mis":"K2-1-u8-X16"}],"explanation":["그린 인물을 오린 뒤 막대를 붙여요.","표를 사는 것은 만드는 차례가 아니에요.","공연은 다 만든 뒤에 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#2','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'mc','auto','모둠 계획을 읽고 답해 보세요. 호랑이 역할을 맡은 친구는 누구인가요?',ARRAY['K2-1-u8-X04']::text[],true,'{"seq":2,"concept":"K2-1-u8-C12","difficulty":1,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 호랑이 역할을 맡은 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"아린","mis":"K2-1-u8-X04"},{"t":"지호","mis":"K2-1-u8-X04"}],"explanation":["호랑이는 도윤이가 맡았어요.","아린이는 오빠 역이에요.","지호는 해설을 맡았어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"},"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 답해 보세요. 흥부 역할을 맡은 친구는 누구인가요?","options":[{"t":"현우","correct":true},{"t":"예린","mis":"K2-1-u8-X04"},{"t":"건우","mis":"K2-1-u8-X04"}],"explanation":["흥부는 현우가 맡았어요.","예린이는 흥부 아내 역이에요.","건우는 해설을 맡았어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#3','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'ox','auto','막대 인형은 인물의 특징만 살려 간단하게 만들어요.',ARRAY['K2-1-u8-X16']::text[],true,'{"seq":3,"concept":"K2-1-u8-C12","difficulty":1,"kind":"ox","stem":"막대 인형은 인물의 특징만 살려 간단하게 만들어요.","answer":"O","reason_options":[{"t":"인형을 완성하는 것보다 인형극 놀이가 더 중요하니까","correct":true},{"t":"인형을 아주 정교하게 꾸미는 것이 가장 중요하니까","mis":"K2-1-u8-X16"}],"mis":"K2-1-u8-X16","explanation":["간단히 만들고 인형극 놀이에 시간을 써요.","인물의 특징만 드러나면 충분해요.","마음을 살린 대사와 움직임 연습이 더 중요해요."],"variant_rule":{"alt":[{"stem":"친구들의 인형극을 볼 때는 무대 앞으로 나가 인형을 만져 봐요.","answer":"X","reason_options":[{"t":"자리에 앉아 바른 자세로 봐야 공연을 방해하지 않으니까","correct":true},{"t":"가까이 가야 인형이 더 잘 보이니까","mis":"K2-1-u8-X17"}],"explanation":["무대 앞으로 나가면 공연이 멈춰요.","자리에서 조용히 바른 자세로 봐요.","끝난 뒤 좋았던 점을 이야기해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#4','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',1,'mc','auto','인형극을 발표하는 친구가 지킬 약속으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16']::text[],true,'{"seq":4,"concept":"K2-1-u8-C12","difficulty":1,"kind":"mc","stem":"인형극을 발표하는 친구가 지킬 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"관객이 잘 듣도록 또박또박 천천히 대사를 말해요","correct":true},{"t":"관객에게 등을 돌리고 대사를 말해요","mis":"K2-1-u8-X16"},{"t":"대사를 아무 느낌 없이 빨리 읽어요","mis":"K2-1-u8-X16"}],"explanation":["또박또박 천천히 말해야 관객이 잘 들어요.","등을 돌리면 목소리가 잘 들리지 않아요.","느낌 없이 빨리 읽으면 인물의 마음이 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"인형극을 보는 친구가 지킬 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"끝나면 박수를 치고 좋았던 점을 말해요","correct":true},{"t":"공연 중에 크게 떠들어요","mis":"K2-1-u8-X17"},{"t":"공연 중간에 일어나 돌아다녀요","mis":"K2-1-u8-X17"}],"explanation":["박수와 칭찬은 공연한 친구에게 힘이 돼요.","떠들면 대사가 들리지 않아요.","돌아다니면 공연을 방해해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#5','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'match','auto','인형극에서 맡는 역할과 하는 일을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u8-C12","difficulty":2,"kind":"match","stem":"인형극에서 맡는 역할과 하는 일을 알맞게 이어 보세요.","pairs":[{"l":"인형 움직이기","r":"인물에 맞게 인형을 움직여요"},{"l":"대사 말하기","r":"인물의 마음을 살려 말을 해요"},{"l":"해설","r":"장면이나 상황을 설명해요"}],"mis":"K2-1-u8-X16","explanation":["인형을 움직이는 친구는 인물답게 움직여요.","대사는 마음을 살려 말해요.","해설은 장면을 알려 줘요."],"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 인물과 그 역할을 맡은 친구를 알맞게 이어 보세요.","pairs":[{"l":"호랑이","r":"도윤"},{"l":"오빠","r":"아린"},{"l":"해설","r":"지호"}],"explanation":["호랑이는 도윤이가 맡았어요.","오빠는 아린이가 맡았어요.","해설은 지호가 맡았어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#6','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'mc','auto','모둠 계획을 읽고 답해 보세요. 3모둠이 보여 줄 장면은 무엇인가요?',ARRAY['K2-1-u8-X04']::text[],true,'{"seq":6,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 3모둠이 보여 줄 장면은 무엇인가요?","options":[{"t":"호랑이가 문을 두드리는 장면","correct":true},{"t":"오누이가 동아줄을 잡는 장면","mis":"K2-1-u8-X04"},{"t":"흥부네가 박을 타는 장면","mis":"K2-1-u8-X04"}],"explanation":["계획표에 호랑이가 문을 두드리는 장면이라고 했어요.","동아줄 장면은 3모둠이 고른 장면이 아니에요.","박을 타는 장면은 1모둠이 고른 장면이에요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"},"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 답해 보세요. 1모둠이 보여 줄 장면은 무엇인가요?","options":[{"t":"흥부네가 박을 타는 장면","correct":true},{"t":"호랑이가 문을 두드리는 장면","mis":"K2-1-u8-X04"},{"t":"형과 아우가 마주치는 장면","mis":"K2-1-u8-X04"}],"explanation":["계획표에 흥부네가 박을 타는 장면이라고 했어요.","호랑이 장면은 3모둠이 고른 장면이에요.","형과 아우 장면은 다른 작품이에요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#7','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'mc','auto','인형극에서 호랑이가 「얘들아, 엄마 왔다. 문 열어라.」라고 말할 때 무서운 느낌을 살리는 목소리는 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X16']::text[],true,'{"seq":7,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"인형극에서 호랑이가 「얘들아, 엄마 왔다. 문 열어라.」라고 말할 때 무서운 느낌을 살리는 목소리는 어느 것인가요?","options":[{"t":"굵고 느린 목소리","correct":true},{"t":"작고 귀여운 목소리","mis":"K2-1-u8-X12"},{"t":"아무 느낌 없이 빠르게 읽는 목소리","mis":"K2-1-u8-X16"}],"explanation":["굵고 느린 목소리가 호랑이의 무서운 느낌을 살려요.","작고 귀여운 목소리는 무서운 호랑이와 맞지 않아요.","느낌 없이 빨리 읽으면 인물이 살아나지 않아요."],"variant_rule":{"alt":[{"stem":"인형극에서 흥부가 「아이고, 이게 웬 쌀이오!」라고 말할 때 마음을 살리는 목소리는 어느 것인가요?","options":[{"t":"깜짝 놀라 들뜬 커다란 목소리","correct":true},{"t":"힘없이 축 처진 목소리","mis":"K2-1-u8-X12"},{"t":"아무 느낌 없이 빠르게 읽는 목소리","mis":"K2-1-u8-X16"}],"explanation":["놀랍고 기쁜 마음은 들뜬 큰 목소리로 살아나요.","축 처진 목소리는 슬플 때 어울려요.","느낌 없이 읽으면 마음이 전해지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#8','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'error','auto','친구들이 인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X19']::text[],true,'{"seq":8,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"친구들이 인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?","options":[{"t":"하람 — 공연 중에 「저거 틀렸다!」 하고 크게 외쳤어요","correct":true,"mis_target":"K2-1-u8-X17"},{"t":"윤서 — 자리에 앉아 조용히 끝까지 보았어요","mis":"K2-1-u8-X19"},{"t":"민호 — 공연이 끝나자 박수를 치고 좋았던 점을 말했어요","mis":"K2-1-u8-X19"}],"explanation":["공연 중에 외치면 공연하는 친구가 당황해요.","윤서와 민호는 바른 자세로 보았어요.","물음의 「바르지 않게」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"모둠이 인형극을 준비하는 모습이에요. 바르지 않게 준비한 모둠은 어느 것인가요?","options":[{"t":"2모둠 — 인형을 꾸미느라 대사 연습을 한 번도 하지 않았어요","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"4모둠 — 인형을 간단히 만들고 대사를 여러 번 연습했어요","mis":"K2-1-u8-X19"},{"t":"5모둠 — 모두가 한 가지씩 역할을 나누어 맡았어요","mis":"K2-1-u8-X19"}],"explanation":["인형 꾸미기보다 인형극 놀이와 연습이 더 중요해요.","4모둠과 5모둠은 바르게 준비했어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#9','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',2,'sa','auto','모둠 계획을 읽고 답해 보세요. 준비물 가운데 종이 인형을 붙여 손으로 잡고 움직이는 것을 두 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u8-C12","difficulty":2,"kind":"sa","stem":"모둠 계획을 읽고 답해 보세요. 준비물 가운데 종이 인형을 붙여 손으로 잡고 움직이는 것을 두 글자로 써 보세요.","answer":["막대"],"explanation":["막대에 인형을 붙여 잡고 움직여요.","그래서 막대 인형극이라고 해요.","계획표의 준비물을 짚어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"},"variant_rule":{"alt":[{"stem":"모둠 계획을 읽고 답해 보세요. 1모둠에서 해설을 맡은 친구의 이름을 써 보세요.","answer":["건우"],"explanation":["해설은 건우가 맡았어요.","해설은 장면이나 상황을 설명해요.","계획표의 역할을 짚어요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_basic#10','kor',2,1,'u8','L12','g2_1_kor_u8_L12_basic','lesson_basic','K2-1-u8-C12',3,'mc','auto','인형극을 할 때 이야기 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X17']::text[],true,'{"seq":10,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"인형극을 할 때 이야기 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?","options":[{"t":"짧은 장면이라도 인물의 마음을 살려 실감 나게 보여 줄 수 있어서","correct":true},{"t":"연습을 하지 않아도 되어서","mis":"K2-1-u8-X16"},{"t":"관객이 보지 않아도 되어서","mis":"K2-1-u8-X17"}],"explanation":["한 장면에 집중하면 목소리와 움직임을 더 살릴 수 있어요.","한 장면이라도 연습은 꼭 해야 해요.","관객도 바른 자세로 끝까지 봐요."],"variant_rule":{"alt":[{"stem":"인형극을 할 때 모둠 친구들이 역할을 골고루 나누어 맡는 까닭은 무엇인가요?","options":[{"t":"모두가 인형극에 함께 참여할 수 있어서","correct":true},{"t":"한 사람만 힘들게 하려고","mis":"K2-1-u8-X16"},{"t":"구경만 하는 친구가 많아지라고","mis":"K2-1-u8-X16"}],"explanation":["역할을 나누면 모두가 함께 즐길 수 있어요.","한 사람만 힘들면 함께하는 인형극이 아니에요.","모두가 맡은 일이 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#1','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',2,'mc','auto','모둠 계획을 읽고 답해 보세요. 흥부 아내 역할을 맡은 친구는 누구인가요?',ARRAY['K2-1-u8-X04']::text[],false,'{"seq":1,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 흥부 아내 역할을 맡은 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"다은","mis":"K2-1-u8-X04"},{"t":"현우","mis":"K2-1-u8-X04"}],"explanation":["흥부 아내는 예린이가 맡았어요.","다은이는 아이들 역이에요.","현우는 흥부 역이에요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#2','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',2,'mc','auto','막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16']::text[],false,'{"seq":2,"concept":"K2-1-u8-C12","difficulty":2,"kind":"mc","stem":"막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인물 그리기 → 오리기 → 막대 붙이기 → 움직여 보기","correct":true},{"t":"막대 붙이기 → 인물 그리기 → 오리기 → 움직여 보기","mis":"K2-1-u8-X16"},{"t":"오리기 → 움직여 보기 → 인물 그리기 → 막대 붙이기","mis":"K2-1-u8-X16"}],"explanation":["그리고, 오리고, 막대를 붙인 뒤 움직여 봐요.","그리기 전에 막대를 붙일 수 없어요.","그리지 않은 종이는 오릴 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#3','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'mc','auto','모둠 계획을 읽고 답해 보세요. 오빠 역을 맡은 아린이가 「얼른 나무 위로 올라가자!」라고 말할 때 인형을 움직이는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X17']::text[],false,'{"seq":3,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 오빠 역을 맡은 아린이가 「얼른 나무 위로 올라가자!」라고 말할 때 인형을 움직이는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누이 인형 곁에 붙어 서둘러 무대 옆으로 빠져나가게 움직여요","correct":true},{"t":"인형을 가만히 세워 두어요","mis":"K2-1-u8-X16"},{"t":"인형을 관객 쪽으로 던져요","mis":"K2-1-u8-X17"}],"explanation":["달아나는 급한 마음이 서두르는 움직임으로 살아나요.","가만히 있으면 급한 마음이 드러나지 않아요.","인형을 던지면 위험하고 공연이 망가져요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#4','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'error','auto','모둠이 인형극 준비를 하며 낸 의견이에요. 바르지 않은 의견을 낸 친구는 누구인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X19']::text[],false,'{"seq":4,"concept":"K2-1-u8-C12","difficulty":3,"kind":"error","stem":"모둠이 인형극 준비를 하며 낸 의견이에요. 바르지 않은 의견을 낸 친구는 누구인가요?","options":[{"t":"소율 — 「대사는 외우기 어려우니까 아무 느낌 없이 빨리 읽고 끝내자.」","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"지호 — 「해설은 장면을 천천히 알려 주면 좋겠어.」","mis":"K2-1-u8-X19"},{"t":"도윤 — 「호랑이는 굵고 느린 목소리로 하면 더 무섭겠다.」","mis":"K2-1-u8-X19"}],"explanation":["느낌 없이 빨리 읽으면 인물의 마음이 전해지지 않아요.","지호와 도윤이는 인물과 장면을 살리는 의견을 냈어요.","물음의 「바르지 않은」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「해와 달이 된 오누이」","보여 줄 장면: 호랑이가 문을 두드리는 장면","맡은 역할: 호랑이 — 도윤 · 오빠 — 아린 · 누이 — 소율 · 해설 — 지호","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"3모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#5','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'ox','auto','인형극을 보고 나면 좋았던 점과 인물의 마음이 잘 드러난 부분을 서로 이야기해요.',ARRAY['K2-1-u8-X17']::text[],false,'{"seq":5,"concept":"K2-1-u8-C12","difficulty":3,"kind":"ox","stem":"인형극을 보고 나면 좋았던 점과 인물의 마음이 잘 드러난 부분을 서로 이야기해요.","answer":"O","reason_options":[{"t":"감상을 나누면 작품을 더 깊이 느끼고 공연한 친구도 힘이 나니까","correct":true},{"t":"인형극은 보고 나면 그대로 끝나는 것이니까","mis":"K2-1-u8-X17"}],"mis":"K2-1-u8-X17","explanation":["보고 난 뒤 감상을 나누는 것도 중요한 활동이에요.","좋았던 점을 말해 주면 친구가 기뻐해요.","인물의 마음이 잘 드러난 부분을 찾아 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#6','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'mc','auto','「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X04']::text[],false,'{"seq":6,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「엄마를 기다리던 깊은 밤, 누군가 문을 두드려요.」","correct":true},{"t":"「얘들아, 엄마 왔다. 문 열어라.」","mis":"K2-1-u8-X04"},{"t":"「얼른 나무 위로 올라가자!」","mis":"K2-1-u8-X04"}],"explanation":["해설은 장면과 상황을 알려 주는 말을 해요.","「문 열어라.」는 호랑이의 대사예요.","「올라가자!」는 오빠의 대사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#7','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',3,'mc','auto','인형극 공연 중에 한 친구가 대사를 잊어버렸어요. 보는 친구들이 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X17']::text[],false,'{"seq":7,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"인형극 공연 중에 한 친구가 대사를 잊어버렸어요. 보는 친구들이 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"조용히 기다려 주고 끝나면 응원해 줘요","correct":true},{"t":"큰 소리로 웃어요","mis":"K2-1-u8-X17"},{"t":"대신 대사를 크게 외쳐 줘요","mis":"K2-1-u8-X17"}],"explanation":["기다려 주면 친구가 마음을 가다듬을 수 있어요.","웃으면 친구가 더 당황해요.","대신 외치면 공연이 엉켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#8','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'mc','auto','모둠 계획을 읽고 답해 보세요. 1모둠이 흥부네의 기쁜 마음을 가장 잘 살리는 계획은 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X16']::text[],false,'{"seq":8,"concept":"K2-1-u8-C12","difficulty":4,"kind":"mc","stem":"모둠 계획을 읽고 답해 보세요. 1모둠이 흥부네의 기쁜 마음을 가장 잘 살리는 계획은 어느 것인가요?","options":[{"t":"쌀이 쏟아질 때 흥부는 깜짝 놀란 큰 목소리로 말하고, 아이들 인형은 깡충깡충 뛰게 움직여요","correct":true},{"t":"모두 작은 목소리로 천천히 말하고 인형은 가만히 둬요","mis":"K2-1-u8-X12"},{"t":"인형 꾸미기에 시간을 다 쓰고 대사는 공연 때 처음 읽어요","mis":"K2-1-u8-X16"}],"explanation":["목소리와 움직임이 함께 기쁜 마음을 살려요.","작고 느린 목소리와 멈춘 인형은 기쁜 장면과 맞지 않아요.","연습 없이 처음 읽으면 마음이 살지 않아요."],"asset":{"type":"passage","lines":["보여 줄 작품: 「흥부와 놀부」","보여 줄 장면: 흥부네가 박을 타는 장면","맡은 역할: 흥부 — 현우 · 흥부 아내 — 예린 · 아이들 — 다은 · 해설 — 건우","준비물: 막대, 두꺼운 종이, 색연필, 가위, 테이프"],"title":"1모둠 인형극 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#9','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'essay','teacher','우리 모둠이 인형극을 한다면 어떤 작품의 어떤 장면을 보여 주고 싶은지, 내가 맡고 싶은 역할과 그 인물의 마음을 살리는 목소리·움직임을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C12","difficulty":4,"kind":"essay","stem":"우리 모둠이 인형극을 한다면 어떤 작품의 어떤 장면을 보여 주고 싶은지, 내가 맡고 싶은 역할과 그 인물의 마음을 살리는 목소리·움직임을 써 보세요.","answer_guide":{"answer":"예: 「의좋은 형제」에서 달밤에 형과 아우가 마주치는 장면을 보여 주고 싶어요. 저는 아우 역을 맡아 처음에는 깜짝 놀란 목소리로, 나중에는 눈물을 글썽이는 떨리는 목소리로 말하고 형 인형 쪽으로 천천히 다가가게 움직이겠어요.","scoring_points":["보여 줄 작품과 장면을 썼는가","맡고 싶은 역할을 썼는가","인물의 마음을 살리는 목소리·움직임을 썼는가"]},"explanation":["작품과 장면.","맡고 싶은 역할.","마음을 살리는 목소리·움직임."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#10','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'essay','teacher','친구 모둠의 인형극을 보았다고 생각하고, 좋았던 점과 인물의 마음이 잘 드러난 부분을 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C12","difficulty":4,"kind":"essay","stem":"친구 모둠의 인형극을 보았다고 생각하고, 좋았던 점과 인물의 마음이 잘 드러난 부분을 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 3모둠의 「해와 달이 된 오누이」가 좋았어요. 호랑이가 굵고 느린 목소리로 「문 열어라.」라고 할 때 정말 무서웠어요. 누이가 떨리는 목소리로 말할 때 무서워하는 마음이 잘 느껴졌어요.","scoring_points":["좋았던 점을 썼는가","인물의 마음이 잘 드러난 부분을 썼는가","목소리·움직임 등 까닭을 들었는가"]},"explanation":["좋았던 점.","마음이 잘 드러난 부분.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#1','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C1',1,'mc','auto','소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"소리 내어 낭송하며 말의 리듬을 즐기는 작품은 어느 것인가요?","options":[{"t":"시","correct":true},{"t":"인형극","mis":"K2-1-u8-X01"},{"t":"이야기","mis":"K2-1-u8-X01"}],"explanation":["시는 리듬을 살려 낭송하며 즐겨요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#2','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C2',1,'mc','auto','인물의 마음이 글에 쓰여 있지 않을 때 무엇을 보고 상상하면 좋을까요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"인물의 마음이 글에 쓰여 있지 않을 때 무엇을 보고 상상하면 좋을까요?","options":[{"t":"인물의 상황과 말·행동","correct":true},{"t":"인물이 입은 옷의 색깔","mis":"K2-1-u8-X06"},{"t":"책의 쪽수","mis":"K2-1-u8-X06"}],"explanation":["상황과 말·행동에 마음이 담겨 있어요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#3','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"살금살금","correct":true},{"t":"동생","mis":"K2-1-u8-X07"},{"t":"이불","mis":"K2-1-u8-X07"}],"explanation":["「살금살금」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#4','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내민 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보에게 당근 김밥을 내민 인물은 누구인가요?","options":[{"t":"토토","correct":true},{"t":"다미","mis":"K2-1-u8-X04"},{"t":"엄마 곰","mis":"K2-1-u8-X03"}],"explanation":["토토가 「우리 같이 먹자!」라며 김밥을 내밀었어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#5','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',1,'mc','auto','빛을 비추어 생긴 그림자로 보여 주는 인형극은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"빛을 비추어 생긴 그림자로 보여 주는 인형극은 어느 것인가요?","options":[{"t":"그림자 인형극","correct":true},{"t":"손가락 인형극","mis":"K2-1-u8-X11"},{"t":"막대 인형극","mis":"K2-1-u8-X11"}],"explanation":["빛과 그림자로 보여 주는 것이 그림자 인형극이에요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#6','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C11',1,'mc','auto','감상을 발표할 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"감상을 발표할 때 바른 자세는 어느 것인가요?","options":[{"t":"또박또박 말하고 까닭도 함께 말해요","correct":true},{"t":"작은 목소리로 웅얼거려요","mis":"K2-1-u8-X15"},{"t":"바닥만 보며 빨리 끝내요","mis":"K2-1-u8-X15"}],"explanation":["또박또박 까닭과 함께 말하면 잘 전해져요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#7','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',1,'mc','auto','「구름이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「구름이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[구르미]","correct":true},{"t":"[구름이]","mis":"K2-1-u8-X18"},{"t":"[구르니]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [구르미]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#8','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',1,'ox','auto','시를 낭송할 때는 시의 리듬과 느낌을 살려 읽어요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"시를 낭송할 때는 시의 리듬과 느낌을 살려 읽어요.","answer":"O","reason_options":[{"t":"리듬과 느낌을 살리면 시가 생생하게 느껴지니까","correct":true},{"t":"시는 언제나 크고 빠르게만 읽어야 하니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["리듬과 느낌을 살려 낭송해요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#9','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」에 담긴 「나」의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「나도 두 팔을 번쩍 들어」에 담긴 「나」의 마음은 무엇인가요?","options":[{"t":"무척 반가운 마음","correct":true},{"t":"짝꿍이 미운 마음","mis":"K2-1-u8-X05"},{"t":"학교에 가기 싫은 마음","mis":"K2-1-u8-X06"}],"explanation":["팔을 번쩍 드는 행동에 반가움이 담겨 있어요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#10','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시무룩하다 → 고맙고 기쁘다","correct":true},{"t":"고맙고 기쁘다 → 시무룩하다","mis":"K2-1-u8-X09"},{"t":"처음부터 끝까지 기쁘다","mis":"K2-1-u8-X09"}],"explanation":["빈 도시락에 시무룩했다가 친구들 덕분에 기뻐졌어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#11','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"지후 — 「나는 보보가 활짝 웃는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"아린 — 「다미가 빵을 나누는 장면이 기억에 남아. 자기 것을 반으로 나눠 준 게 따뜻했거든.」","mis":"K2-1-u8-X19"},{"t":"태민 — 「빈 도시락 장면이 기억에 남아. 내가 보보였으면 울었을 것 같아서.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#12','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"작고 떨리는 목소리","r":"무섭다"},{"l":"크고 빠른 목소리","r":"신난다"},{"l":"느리고 힘없는 목소리","r":"슬프다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#13','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 장소가 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"집 → 고개 → 집 → 나무 위 → 하늘","correct":true},{"t":"고개 → 나무 위 → 집 → 하늘","mis":"K2-1-u8-X13"},{"t":"집 → 나무 위 → 고개 → 하늘","mis":"K2-1-u8-X13"}],"explanation":["엄마가 집을 나서 고개에서 호랑이를 만나고, 호랑이가 집에 온 뒤 오누이는 나무 위를 거쳐 하늘로 갔어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#14','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"눈이 → [누니]","correct":true},{"t":"눈이 → [눈이]","mis":"K2-1-u8-X18"},{"t":"눈이 → [누이]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㄴ이 뒤 글자로 넘어가 [누니]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#15','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 이 편지를 받는 인물은 누구인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 이 편지를 받는 인물은 누구인가요?","options":[{"t":"형","correct":true},{"t":"하준","mis":"K2-1-u8-X14"},{"t":"아우","mis":"K2-1-u8-X14"}],"explanation":["「형님께」라고 썼으니 받는 인물은 형이에요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#16','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C12',2,'error','auto','인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?","options":[{"t":"하람 — 공연 중에 「저거 틀렸다!」 하고 크게 외쳤어요","correct":true,"mis_target":"K2-1-u8-X17"},{"t":"윤서 — 자리에 앉아 조용히 끝까지 보았어요","mis":"K2-1-u8-X19"},{"t":"민호 — 끝나자 박수를 치고 좋았던 점을 말했어요","mis":"K2-1-u8-X19"}],"explanation":["공연 중에 외치면 공연하는 친구가 당황해요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#17','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 볏단이 하나도 줄지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 옮긴 만큼 아우도 형에게 옮겼기 때문에","correct":true},{"t":"이웃이 볏단을 가져다 놓았기 때문에","mis":"K2-1-u8-X03"},{"t":"형이 아우의 볏단을 빼앗았기 때문에","mis":"K2-1-u8-X05"}],"explanation":["서로에게 옮겨서 볏단 수가 그대로였어요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#18','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?","options":[{"t":"채원 — 「흥부는 기뻤을 거야. 박이 지붕 위에 열렸으니까.」","correct":true,"mis_target":"K2-1-u8-X06"},{"t":"하준 — 「흥부는 놀랐을 거야. 눈이 휘둥그레졌으니까.」","mis":"K2-1-u8-X19"},{"t":"지우 — 「아이들은 신났을 거야. 덩실덩실 춤을 추었으니까.」","mis":"K2-1-u8-X19"}],"explanation":["박이 열린 것만으로는 흥부의 마음이 드러나지 않아요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#19','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C11',3,'ox','auto','친구의 감상이 나와 다르면 비슷한 점과 다른 점을 견주며 들어요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구의 감상이 나와 다르면 비슷한 점과 다른 점을 견주며 들어요.","answer":"O","reason_options":[{"t":"견주어 들으면 작품을 더 넓게 감상할 수 있으니까","correct":true},{"t":"나와 다른 감상은 들을 필요가 없으니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["견주어 들으면 감상이 넓어져요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#20','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',3,'ox','auto','「구름이」는 받침 ㅁ이 뒤로 넘어가 [구르미]로 소리 나요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"「구름이」는 받침 ㅁ이 뒤로 넘어가 [구르미]로 소리 나요.","answer":"O","reason_options":[{"t":"받침 뒤에 「ㅇ」으로 시작하는 글자 「이」가 왔으니까","correct":true},{"t":"받침은 언제나 글자 그대로 읽어야 하니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["「이」 앞에서 받침이 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#21','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"작고 부드러운 목소리로 천천히 읽기","correct":true},{"t":"크고 씩씩한 목소리로 빠르게 읽기","mis":"K2-1-u8-X08"},{"t":"화난 목소리로 또박또박 끊어 읽기","mis":"K2-1-u8-X08"}],"explanation":["동생이 잠든 고요한 밤이라 작고 부드럽게 읽어요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#22','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C12',3,'mc','auto','막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"막대 인형을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인물 그리기 → 오리기 → 막대 붙이기 → 움직여 보기","correct":true},{"t":"막대 붙이기 → 인물 그리기 → 오리기 → 움직여 보기","mis":"K2-1-u8-X16"},{"t":"오리기 → 움직여 보기 → 인물 그리기 → 막대 붙이기","mis":"K2-1-u8-X16"}],"explanation":["그리고 오린 뒤 막대를 붙여 움직여 봐요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#23','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C6',4,'essay','teacher','「보보의 빈 도시락」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「보보의 빈 도시락」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 다미가 도토리 빵을 반으로 나누어 주는 장면이 가장 기억에 남아요. 자기 것도 아끼지 않고 나눠 준 마음이 따뜻했기 때문이에요. 저도 짝이 우유를 쏟았을 때 제 휴지를 나눠 준 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#24','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 누이의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 누이의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 누이는 무척 무서웠을 거예요. 떨리는 목소리로 말했고, 문을 열기 전에 손을 먼저 보여 달라고 할 만큼 의심스러웠기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#25','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C10',4,'essay','teacher','「의좋은 형제」의 형에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「의좋은 형제」의 형에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 형님께 — 형님, 식구가 많아 힘드실 텐데 아우를 먼저 생각하신 마음이 멋져요. 저는 동생에게 양보를 잘 못 했는데 형님처럼 해 볼게요. — 2학년 지우 올림","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#1','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C1',1,'mc','auto','인형이 나와 말과 움직임으로 이야기를 보여 주는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"인형이 나와 말과 움직임으로 이야기를 보여 주는 작품은 어느 것인가요?","options":[{"t":"인형극","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"일기","mis":"K2-1-u8-X01"}],"explanation":["인형이 나와 보여 주는 것이 인형극이에요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#2','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C2',1,'mc','auto','「콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.」에서 콩쥐의 마음을 짐작하게 하는 것은 무엇인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"「콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.」에서 콩쥐의 마음을 짐작하게 하는 것은 무엇인가요?","options":[{"t":"주저앉아 우는 행동","correct":true},{"t":"독이라는 물건 이름","mis":"K2-1-u8-X06"},{"t":"글자의 수","mis":"K2-1-u8-X06"}],"explanation":["주저앉아 우는 행동에서 속상한 마음이 보여요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#3','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"흔들흔들","correct":true},{"t":"짝꿍","mis":"K2-1-u8-X07"},{"t":"학교","mis":"K2-1-u8-X07"}],"explanation":["「흔들흔들」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#4','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 연이에게 「같이 접어 보자.」라고 한 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이에게 「같이 접어 보자.」라고 한 인물은 누구인가요?","options":[{"t":"오빠","correct":true},{"t":"연이","mis":"K2-1-u8-X04"},{"t":"아빠","mis":"K2-1-u8-X03"}],"explanation":["오빠가 빙그레 웃으며 그렇게 말했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#5','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',1,'mc','auto','손가락에 인형을 끼워 움직이는 인형극은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"손가락에 인형을 끼워 움직이는 인형극은 어느 것인가요?","options":[{"t":"손가락 인형극","correct":true},{"t":"그림자 인형극","mis":"K2-1-u8-X11"},{"t":"막대 인형극","mis":"K2-1-u8-X11"}],"explanation":["손가락에 끼우는 것이 손가락 인형극이에요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#6','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',1,'mc','auto','친구의 감상을 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"친구의 감상을 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"좋은 점을 찾으며 끝까지 들어요","correct":true},{"t":"나와 다르면 틀렸다고 말해요","mis":"K2-1-u8-X15"},{"t":"짝과 다른 이야기를 해요","mis":"K2-1-u8-X15"}],"explanation":["끝까지 좋은 점을 찾으며 들어요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#7','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',1,'mc','auto','「책이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「책이」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[채기]","correct":true},{"t":"[책이]","mis":"K2-1-u8-X18"},{"t":"[채이]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [채기]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#8','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C3',1,'ox','auto','시는 한 가지 방법으로만 낭송해야 해요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"시는 한 가지 방법으로만 낭송해야 해요.","answer":"X","reason_options":[{"t":"주고받기·몸짓·박자 넣기처럼 여러 방법으로 낭송할 수 있으니까","correct":true},{"t":"다른 방법으로 읽으면 시가 틀리게 되니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["여러 방법으로 낭송할 수 있어요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#9','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「이불을 살며시 덮어 준다」에 담긴 「나」의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「이불을 살며시 덮어 준다」에 담긴 「나」의 마음은 무엇인가요?","options":[{"t":"동생을 아끼는 마음","correct":true},{"t":"동생을 깨우고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"이불이 무거운 마음","mis":"K2-1-u8-X06"}],"explanation":["살며시 덮어 주는 행동에 아끼는 마음이 담겨 있어요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#10','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 연이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"설렌다 → 속상하다 → 기쁘다","correct":true},{"t":"기쁘다 → 설렌다 → 속상하다","mis":"K2-1-u8-X09"},{"t":"속상하다 → 속상하다 → 속상하다","mis":"K2-1-u8-X09"}],"explanation":["배를 띄울 때 설렜고 뒤집히자 속상했고 새 배가 떠가자 기뻤어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#11','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"수빈 — 「나는 종이배가 뒤집히는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"현우 — 「오빠가 같이 접자고 하는 장면이 기억에 남아. 다정한 오빠가 부러웠거든.」","mis":"K2-1-u8-X19"},{"t":"다은 — 「새 배가 떠가는 장면이 기억에 남아. 다시 해서 해낸 게 멋졌거든.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#12','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"속삭이는 작은 목소리","r":"들킬까 봐 조심스럽다"},{"l":"깜짝 놀라 커다란 목소리","r":"놀랍다"},{"l":"노래하듯 흥겨운 목소리","r":"즐겁다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#13','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C8',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"박이 열린다 → 박을 탄다 → 쌀이 쏟아진다","correct":true},{"t":"쌀이 쏟아진다 → 박이 열린다 → 박을 탄다","mis":"K2-1-u8-X13"},{"t":"박을 탄다 → 박이 열린다 → 쌀이 쏟아진다","mis":"K2-1-u8-X13"}],"explanation":["박이 열리고, 박을 타자, 쌀이 쏟아졌어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#14','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"집에 → [지베]","correct":true},{"t":"집에 → [집에]","mis":"K2-1-u8-X18"},{"t":"집에 → [지에]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㅂ이 뒤 글자로 넘어가 [지베]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#15','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 이 편지를 쓴 사람은 누구인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 이 편지를 쓴 사람은 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"보보","mis":"K2-1-u8-X14"},{"t":"토토","mis":"K2-1-u8-X14"}],"explanation":["끝에 「서윤이가」라고 썼어요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#16','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C12',2,'error','auto','인형극을 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"인형극을 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"태민 — 관객에게 등을 돌리고 대사를 웅얼거렸어요","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"채원 — 또박또박 천천히 대사를 말했어요","mis":"K2-1-u8-X19"},{"t":"지호 — 인물의 마음에 맞게 인형을 움직였어요","mis":"K2-1-u8-X19"}],"explanation":["등을 돌리고 웅얼거리면 관객이 들을 수 없어요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#17','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 형이 볏단을 내려놓고 아우를 꼭 안은 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형이 볏단을 내려놓고 아우를 꼭 안은 까닭은 무엇인가요?","options":[{"t":"아우도 자기를 생각해 주었다는 것을 알게 되어서","correct":true},{"t":"볏단을 대신 들어 달라고 하려고","mis":"K2-1-u8-X03"},{"t":"아우가 볏단을 훔쳐 가서 붙잡으려고","mis":"K2-1-u8-X05"}],"explanation":["형은 「네가 나를 생각해 주었구나.」라고 했어요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#18','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"하린 — 「물이 줄줄 새어 나갈 때 콩쥐는 신이 났을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"지안 — 「콩쥐는 막막했을 거야. 주저앉아 울었으니까.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「콩쥐는 고마웠을 거야. 두꺼비를 꼭 끌어안았으니까.」","mis":"K2-1-u8-X19"}],"explanation":["물이 새는데 신이 났을 리 없어요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#19','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',3,'ox','auto','친구가 나와 다른 장면을 골랐다면 친구의 감상이 틀린 거예요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구가 나와 다른 장면을 골랐다면 친구의 감상이 틀린 거예요.","answer":"X","reason_options":[{"t":"저마다 겪은 일과 느낌이 달라 다른 장면을 고를 수 있으니까","correct":true},{"t":"기억에 남는 장면은 모두 같아야 하니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["다른 장면을 고른 것은 틀린 것이 아니에요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#20','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',3,'ox','auto','받침 뒤에 어떤 글자가 와도 받침은 늘 뒤로 넘어가 소리 나요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"받침 뒤에 어떤 글자가 와도 받침은 늘 뒤로 넘어가 소리 나요.","answer":"X","reason_options":[{"t":"받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가니까","correct":true},{"t":"받침은 뒤에 무슨 글자가 오든 넘어가니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["「ㅇ」 앞에서만 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#21','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 낭송하기에 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"「흔들흔들」에서 손을 흔들며 밝은 목소리로 읽기","correct":true},{"t":"졸린 목소리로 작게 웅얼거리기","mis":"K2-1-u8-X08"},{"t":"고개를 숙인 채 아주 빠르게 읽기","mis":"K2-1-u8-X08"}],"explanation":["반가운 시라 밝은 목소리와 손 흔들기가 어울려요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#22','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C12',3,'mc','auto','인형극을 할 때 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"인형극을 할 때 한 편을 다 보여 주기보다 한 장면을 충실히 보여 주면 좋은 까닭은 무엇인가요?","options":[{"t":"짧은 장면이라도 인물의 마음을 살려 실감 나게 보여 줄 수 있어서","correct":true},{"t":"관객이 보지 않아도 되어서","mis":"K2-1-u8-X17"},{"t":"연습을 하지 않아도 되어서","mis":"K2-1-u8-X16"}],"explanation":["한 장면에 집중하면 목소리와 움직임을 더 살릴 수 있어요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#23','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C6',4,'essay','teacher','「연이의 종이배」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「연이의 종이배」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 새 종이배가 돌 옆을 쓱 비켜 떠가는 장면이 가장 기억에 남아요. 실패해도 다시 해서 해낸 모습이 멋졌기 때문이에요. 저도 퍼즐을 여러 번 망쳤다가 끝내 완성해서 기뻤던 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#24','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 오빠의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 오빠의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 오빠는 무섭지만 동생을 지키고 싶었을 거예요. 작은 목소리로 속삭였고, 누이 손을 꼭 잡고 뒷문으로 살금살금 나갔기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"엄마를 기다리던 깊은 밤, 누군가 문을 쾅쾅 두드려요."},{"who":"호랑이","text":"(굵고 느린 목소리로) 얘들아, 엄마 왔다. 문 열어라."},{"who":"오빠","text":"(작은 목소리로 속삭이며) 누이야, 목소리가 엄마랑 달라."},{"who":"누이","text":"(떨리는 목소리로) 그럼 손을 먼저 보여 주세요."},{"who":"호랑이","text":"(털이 숭숭 난 손을 문틈으로 쑥 내밀며) 자, 엄마 손이다."},{"who":"오빠","text":"(누이 손을 꼭 잡고 뒷문으로 살금살금 나가며) 얼른 나무 위로 올라가자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#25','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C10',4,'essay','teacher','「보보의 빈 도시락」의 토토에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「보보의 빈 도시락」의 토토에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 토토에게 — 토토야, 혼자 있던 보보에게 먼저 다가가 줘서 정말 멋졌어. 나도 쉬는 시간에 혼자 있는 친구에게 먼저 같이 놀자고 할게. — 하윤이가","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#1','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C1',1,'mc','auto','인물이 겪은 일을 차례대로 들려주는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"인물이 겪은 일을 차례대로 들려주는 작품은 어느 것인가요?","options":[{"t":"이야기","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"인형극","mis":"K2-1-u8-X01"}],"explanation":["이야기에는 인물과 일어난 일이 차례대로 나와요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#2','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C2',1,'mc','auto','「흥부는 눈이 휘둥그레져 입을 다물지 못했어요.」에서 흥부의 마음을 짐작하게 하는 것은 무엇인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"「흥부는 눈이 휘둥그레져 입을 다물지 못했어요.」에서 흥부의 마음을 짐작하게 하는 것은 무엇인가요?","options":[{"t":"눈이 휘둥그레진 행동","correct":true},{"t":"흥부라는 이름","mis":"K2-1-u8-X06"},{"t":"문장의 길이","mis":"K2-1-u8-X06"}],"explanation":["휘둥그레진 눈에서 놀란 마음이 보여요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#3','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K2-1-u8-X07"},{"t":"김밥","mis":"K2-1-u8-X07"}],"explanation":["「깡충깡충」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#4','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 도토리 빵을 반으로 나누어 준 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 도토리 빵을 반으로 나누어 준 인물은 누구인가요?","options":[{"t":"다미","correct":true},{"t":"토토","mis":"K2-1-u8-X04"},{"t":"보보","mis":"K2-1-u8-X03"}],"explanation":["다람쥐 다미가 빵을 나누어 주었어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#5','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C7',1,'mc','auto','막대에 붙인 인형을 잡고 움직이는 인형극은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"막대에 붙인 인형을 잡고 움직이는 인형극은 어느 것인가요?","options":[{"t":"막대 인형극","correct":true},{"t":"그림자 인형극","mis":"K2-1-u8-X11"},{"t":"손가락 인형극","mis":"K2-1-u8-X11"}],"explanation":["막대로 움직이는 것이 막대 인형극이에요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#6','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C11',1,'mc','auto','감상을 발표할 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"감상을 발표할 때 바른 자세는 어느 것인가요?","options":[{"t":"친구들을 바라보며 알맞은 목소리로 말해요","correct":true},{"t":"친구들에게 등을 돌리고 말해요","mis":"K2-1-u8-X15"},{"t":"종이로 얼굴을 가리고 말해요","mis":"K2-1-u8-X15"}],"explanation":["친구들을 바라보면 마음이 잘 전해져요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#7','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C13',1,'mc','auto','「손에」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「손에」를 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[소네]","correct":true},{"t":"[손에]","mis":"K2-1-u8-X18"},{"t":"[소에]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [소네]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#8','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C3',1,'ox','auto','조용한 밤을 그린 시는 큰 소리로 외치듯 읽어야 어울려요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"조용한 밤을 그린 시는 큰 소리로 외치듯 읽어야 어울려요.","answer":"X","reason_options":[{"t":"조용한 시는 작고 부드러운 목소리가 어울리니까","correct":true},{"t":"시는 무조건 크게 읽어야 잘 들리니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["시의 분위기에 맞는 목소리로 읽어요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#9','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「우리 둘은 벌써 웃는다」에서 알 수 있는 두 사람의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「우리 둘은 벌써 웃는다」에서 알 수 있는 두 사람의 마음은 무엇인가요?","options":[{"t":"서로 반갑고 즐거운 마음","correct":true},{"t":"서로 화가 난 마음","mis":"K2-1-u8-X05"},{"t":"학교 앞이 낯선 마음","mis":"K2-1-u8-X06"}],"explanation":["말없이 웃는 모습에 반가운 마음이 보여요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#10','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 보보의 마음이 바뀌게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 보보의 마음이 바뀌게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"토토와 다미가 음식을 나누어 주어서","correct":true},{"t":"도시락이 텅 비어 있어서","mis":"K2-1-u8-X09"},{"t":"소풍이 일찍 끝나서","mis":"K2-1-u8-X09"}],"explanation":["친구들이 음식을 나눠 주어 시무룩하던 마음이 기뻐졌어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["오늘은 숲속 친구들이 소풍 가는 날이에요.","아기 곰 보보는 도시락 뚜껑을 열다가 깜짝 놀랐어요. 도시락이 텅 비어 있었거든요.","보보는 고개를 푹 숙이고 커다란 나무 뒤에 혼자 앉았어요.","그때 토끼 토토가 깡충깡충 다가와 당근 김밥을 내밀었어요. 「우리 같이 먹자!」","다람쥐 다미도 도토리 빵을 반으로 뚝 나누어 주었어요.","보보는 눈이 동그래졌다가 이내 활짝 웃었어요. 「얘들아, 정말 고마워!」"],"title":"보보의 빈 도시락"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#11','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"예린 — 「나는 형과 아우가 마주치는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"하준 — 「볏단이 줄지 않는 장면이 기억에 남아. 왜 그런지 궁금해서 두근두근했거든.」","mis":"K2-1-u8-X19"},{"t":"소율 — 「형이 아우를 안는 장면이 기억에 남아. 내 마음까지 따뜻해졌거든.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#12','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"굵고 느린 목소리","r":"무섭고 위협적이다"},{"l":"울먹이는 목소리","r":"서럽다"},{"l":"들뜬 큰 목소리","r":"기쁘다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#13','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C8',2,'mc','auto','인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 일이 일어난 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 볏단을 옮긴다 → 아우도 볏단을 옮긴다 → 다음 날 볏단이 줄지 않아 놀란다","correct":true},{"t":"다음 날 볏단이 줄지 않아 놀란다 → 형이 볏단을 옮긴다 → 아우도 볏단을 옮긴다","mis":"K2-1-u8-X13"},{"t":"아우가 볏단을 옮긴다 → 다음 날 볏단이 줄지 않아 놀란다 → 형이 볏단을 옮긴다","mis":"K2-1-u8-X13"}],"explanation":["두 사람이 밤에 옮긴 뒤 다음 날 아침 놀랐어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#14','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"옷을 → [오슬]","correct":true},{"t":"옷을 → [옷을]","mis":"K2-1-u8-X18"},{"t":"옷을 → [오을]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㅅ이 뒤 글자로 넘어가 [오슬]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#15','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 하준이가 형에게 하고 싶은 말을 한 까닭으로 든 것은 무엇인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 하준이가 형에게 하고 싶은 말을 한 까닭으로 든 것은 무엇인가요?","options":[{"t":"동생에게 장난감을 잘 빌려주지 않았던 일","correct":true},{"t":"형님이 볏단을 빼앗은 일","mis":"K2-1-u8-X14"},{"t":"아우가 편지를 보낸 일","mis":"K2-1-u8-X14"}],"explanation":["하준이는 자기 경험을 까닭으로 들었어요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["형님께","형님, 아우를 위해 밤마다 무거운 볏단을 몰래 옮기신 장면을 보고 마음이 따뜻해졌어요.","저도 동생이 있는데 장난감을 잘 빌려주지 않았거든요.","이제는 형님처럼 동생을 먼저 생각해 볼게요.","— 2학년 하준 올림"],"title":"하준이가 형에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#16','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C12',2,'error','auto','인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?',ARRAY['K2-1-u8-X17','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"인형극을 보는 모습이에요. 바르지 않게 본 친구는 누구인가요?","options":[{"t":"도담 — 공연 중에 무대 앞으로 나가 인형을 만졌어요","correct":true,"mis_target":"K2-1-u8-X17"},{"t":"다은 — 대사를 잊은 친구를 조용히 기다려 주었어요","mis":"K2-1-u8-X19"},{"t":"하늘 — 인물의 마음이 잘 드러난 부분을 기억해 두었어요","mis":"K2-1-u8-X19"}],"explanation":["무대 앞으로 나가면 공연이 멈춰요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#17','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 형과 아우가 볏단을 「몰래」 옮긴 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 형과 아우가 볏단을 「몰래」 옮긴 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"미리 말하면 상대가 사양하고 받지 않을 것 같아서","correct":true},{"t":"볏단 옮기는 일이 부끄러워서","mis":"K2-1-u8-X03"},{"t":"상대를 놀라게 해 골탕 먹이려고","mis":"K2-1-u8-X05"}],"explanation":["상대를 위하는 마음을 부담 없이 전하려고 몰래 옮겼을 거예요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"가을걷이가 끝난 밤이에요."},{"who":"형","text":"(볏단을 지게에 지고 살금살금 걸으며) 아우는 살림을 막 차려서 쌀이 더 필요할 거야."},{"who":"해설","text":"같은 밤, 아우도 볏단을 지고 몰래 집을 나서요."},{"who":"아우","text":"(조용한 목소리로) 형님은 식구가 많으니 볏단이 더 있어야 해."},{"who":"해설","text":"다음 날 아침, 두 사람은 볏단 더미 앞에서 고개를 갸웃해요."},{"who":"형과 아우","text":"(깜짝 놀란 목소리로) 어? 볏단이 하나도 줄지 않았네!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#18','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?',ARRAY['K2-1-u8-X06','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 까닭을 알맞지 않게 든 친구는 누구인가요?","options":[{"t":"민호 — 「콩쥐는 속상했을 거야. 독이 커다랬으니까.」","correct":true,"mis_target":"K2-1-u8-X06"},{"t":"서아 — 「콩쥐는 속상했을 거야. 훌쩍훌쩍 울었으니까.」","mis":"K2-1-u8-X19"},{"t":"도윤 — 「콩쥐는 안심했을 거야. 물이 찰랑찰랑 차올랐으니까.」","mis":"K2-1-u8-X19"}],"explanation":["독이 큰 것은 콩쥐의 마음이 드러나는 부분이 아니에요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#19','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C11',3,'ox','auto','친구의 감상 발표를 들을 때는 좋은 점을 찾으며 끝까지 들어요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"친구의 감상 발표를 들을 때는 좋은 점을 찾으며 끝까지 들어요.","answer":"O","reason_options":[{"t":"좋은 점을 찾으면 친구의 생각을 배우고 친구도 힘이 나니까","correct":true},{"t":"듣는 동안 내가 할 말만 생각하면 되니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["끝까지 좋은 점을 찾으며 들어요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#20','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C13',3,'ox','auto','「꽃이」를 소리 나는 대로 쓰면 [꼬치]예요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"「꽃이」를 소리 나는 대로 쓰면 [꼬치]예요.","answer":"O","reason_options":[{"t":"받침 ㅊ이 뒤 글자 「이」로 넘어가 소리 나니까","correct":true},{"t":"받침 ㅊ은 넘어가지 않고 사라지니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["받침 ㅊ도 「ㅇ」 앞에서 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#21','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 친구와 「주고받기」로 낭송하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 친구와 「주고받기」로 낭송하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"짝꿍 역은 1·2행, 나 역은 3·4행, 마지막 두 행은 함께 읽기","correct":true},{"t":"한 사람이 처음부터 끝까지 혼자 읽기","mis":"K2-1-u8-X08"},{"t":"두 사람이 같은 행을 겹쳐 읽기","mis":"K2-1-u8-X08"}],"explanation":["주고받으며 읽으면 손 인사를 주고받는 느낌이 살아요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["저만치 학교 앞에서","짝꿍이 손을 흔든다","나도 두 팔을 번쩍 들어","흔들흔들 흔들어 준다","말 한마디 안 했는데","우리 둘은 벌써 웃는다"],"title":"손 흔들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#22','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C12',3,'mc','auto','「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"「해와 달이 된 오누이」 인형극에서 해설이 하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「엄마를 기다리던 깊은 밤, 누군가 문을 두드려요.」","correct":true},{"t":"「얘들아, 엄마 왔다. 문 열어라.」","mis":"K2-1-u8-X04"},{"t":"「얼른 나무 위로 올라가자!」","mis":"K2-1-u8-X16"}],"explanation":["해설은 장면과 상황을 알려 줘요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#23','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C6',4,'essay','teacher','「의좋은 형제」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「의좋은 형제」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 형이 아우를 꼭 안아 주는 장면이 가장 기억에 남아요. 서로를 몰래 도운 마음을 알게 되어 제 마음도 뭉클했기 때문이에요. 저도 동생이 제 생일 카드를 몰래 만든 것을 알고 감동한 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#24','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 흥부의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 흥부의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 흥부는 깜짝 놀라고 무척 기뻤을 거예요. 쌀이 쏟아지자 커다란 목소리로 「아이고, 이게 웬 쌀이오!」라고 말했기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"박씨가 자라 흥부네 지붕에 커다란 박이 열렸어요."},{"who":"흥부","text":"(신이 나서 빠르게) 여보, 박이 이렇게 컸구려! 어서 타 봅시다."},{"who":"흥부 아내","text":"(노래하듯 흥겹게) 슬근슬근 톱질하세!"},{"who":"해설","text":"쩍! 박이 갈라지자 쌀이 와르르 쏟아져요."},{"who":"흥부","text":"(깜짝 놀라 커다란 목소리로) 아이고, 이게 웬 쌀이오!"},{"who":"아이들","text":"(인형을 깡충깡충 뛰게 하며) 와, 이제 배불리 먹을 수 있다!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#25','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C10',4,'essay','teacher','「연이의 종이배」의 연이에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「연이의 종이배」의 연이에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 연이에게 — 연이야, 종이배가 뒤집혔을 때 많이 속상했지? 그래도 오빠와 다시 접어서 해낸 게 대단해. 나도 실패해도 다시 해 볼게. — 시우가","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#1','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C1',1,'mc','auto','막대에 붙인 인형을 움직여 보여 주는 작품은 어느 것인가요?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":1,"concept":"K2-1-u8-C1","difficulty":1,"kind":"mc","stem":"막대에 붙인 인형을 움직여 보여 주는 작품은 어느 것인가요?","options":[{"t":"인형극","correct":true},{"t":"시","mis":"K2-1-u8-X01"},{"t":"이야기","mis":"K2-1-u8-X01"}],"explanation":["막대 인형극도 인형극의 한 가지예요.","다른 보기는 그 특징과 맞지 않는 작품이에요.","특징을 하나씩 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#2','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C2',1,'mc','auto','「보보는 고개를 푹 숙이고 혼자 앉았어요.」에서 보보의 마음을 짐작하게 하는 것은 무엇인가요?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":2,"concept":"K2-1-u8-C2","difficulty":1,"kind":"mc","stem":"「보보는 고개를 푹 숙이고 혼자 앉았어요.」에서 보보의 마음을 짐작하게 하는 것은 무엇인가요?","options":[{"t":"고개를 푹 숙인 행동","correct":true},{"t":"나무의 크기","mis":"K2-1-u8-X06"},{"t":"보보라는 이름","mis":"K2-1-u8-X06"}],"explanation":["고개를 숙이고 혼자 앉은 행동에서 시무룩한 마음이 보여요.","다른 보기에는 인물의 마음이 드러나지 않아요.","「이 부분에 마음이 보이나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#3','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C4',1,'mc','auto','흉내 내는 말은 어느 것인가요?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":3,"concept":"K2-1-u8-C4","difficulty":1,"kind":"mc","stem":"흉내 내는 말은 어느 것인가요?","options":[{"t":"새근새근","correct":true},{"t":"잠","mis":"K2-1-u8-X07"},{"t":"밤","mis":"K2-1-u8-X07"}],"explanation":["「새근새근」은 소리나 모양을 흉내 낸 말이에요.","다른 두 낱말은 무엇을 가리키는 이름이에요.","몸짓으로 따라 할 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#4','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C5',1,'mc','auto','이야기를 읽고 답해 보세요. 종이배가 뒤집히자 발을 동동 구른 인물은 누구인가요?',ARRAY['K2-1-u8-X04','K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 종이배가 뒤집히자 발을 동동 구른 인물은 누구인가요?","options":[{"t":"연이","correct":true},{"t":"오빠","mis":"K2-1-u8-X04"},{"t":"동생","mis":"K2-1-u8-X03"}],"explanation":["연이가 속상해서 발을 동동 굴렀어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#5','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C7',1,'mc','auto','인형극에서 인물의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X11']::text[],false,'{"seq":5,"concept":"K2-1-u8-C7","difficulty":1,"kind":"mc","stem":"인형극에서 인물의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"인형의 말·움직임·목소리","correct":true},{"t":"무대 막의 색깔","mis":"K2-1-u8-X11"},{"t":"관객의 수","mis":"K2-1-u8-X11"}],"explanation":["말·움직임·목소리에 인물의 마음이 드러나요.","다른 보기는 그 특징과 맞지 않아요.","인형을 무엇으로 움직이는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#6','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C11',1,'mc','auto','친구의 감상을 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":6,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"친구의 감상을 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"내 감상과 비슷한 점·다른 점을 견주며 들어요","correct":true},{"t":"중간에 끼어들어 내 말을 해요","mis":"K2-1-u8-X15"},{"t":"엎드려서 들어요","mis":"K2-1-u8-X15"}],"explanation":["견주어 들으면 감상이 넓어져요.","다른 보기는 바르지 않은 자세예요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#7','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',1,'mc','auto','「밥을」을 소리 내어 읽을 때 나는 소리는 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":7,"concept":"K2-1-u8-C13","difficulty":1,"kind":"mc","stem":"「밥을」을 소리 내어 읽을 때 나는 소리는 어느 것인가요?","options":[{"t":"[바블]","correct":true},{"t":"[밥을]","mis":"K2-1-u8-X18"},{"t":"[바을]","mis":"K2-1-u8-X18"}],"explanation":["받침 뒤에 「ㅇ」으로 시작하는 글자가 와서 받침이 뒤로 넘어가 [바블]로 소리 나요.","글자 그대로 읽으면 자연스럽지 않아요.","받침 뒤 글자가 「ㅇ」인지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#8','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C3',1,'ox','auto','「주고받기」는 두 사람이 한 줄씩 번갈아 읽는 낭송 방법이에요.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":8,"concept":"K2-1-u8-C3","difficulty":1,"kind":"ox","stem":"「주고받기」는 두 사람이 한 줄씩 번갈아 읽는 낭송 방법이에요.","answer":"O","reason_options":[{"t":"번갈아 읽으면 주고받는 느낌이 살아나니까","correct":true},{"t":"주고받기는 모두가 한꺼번에 소리치는 것이니까","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["주고받기는 번갈아 읽는 방법이에요.","시마다 어울리는 낭송 방법이 달라요.","시 분위기를 먼저 정하고 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#9','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C4',2,'mc','auto','시를 읽고 답해 보세요. 「숨도 조용조용 쉰다」에 담긴 「나」의 마음은 무엇인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X06']::text[],false,'{"seq":9,"concept":"K2-1-u8-C4","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 「숨도 조용조용 쉰다」에 담긴 「나」의 마음은 무엇인가요?","options":[{"t":"동생이 깰까 봐 조심하는 마음","correct":true},{"t":"동생과 싸우고 싶은 마음","mis":"K2-1-u8-X05"},{"t":"숨이 차서 힘든 마음","mis":"K2-1-u8-X06"}],"explanation":["숨까지 조용히 쉬는 행동에 조심하는 마음이 담겨 있어요.","다른 보기는 행동과 맞지 않거나 마음이 드러나지 않는 것이에요.","행동 속에 담긴 마음을 찾아요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#10','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C5',2,'mc','auto','이야기를 읽고 답해 보세요. 연이의 마음이 다시 기뻐지게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X09']::text[],false,'{"seq":10,"concept":"K2-1-u8-C5","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 연이의 마음이 다시 기뻐지게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"오빠와 튼튼하게 다시 접은 배가 멀리 떠가서","correct":true},{"t":"종이배가 돌에 걸려 뒤집혀서","mis":"K2-1-u8-X09"},{"t":"오빠가 배를 혼자 가져가서","mis":"K2-1-u8-X09"}],"explanation":["다시 접은 배가 잘 떠가자 기뻐졌어요.","다른 보기는 마음이 바뀐 차례가 맞지 않아요.","처음·가운데·끝 마음을 따로 적어 봐요."],"asset":{"type":"passage","lines":["연이는 오빠와 함께 종이배를 접어 시냇물에 띄웠어요.","종이배는 동동 떠내려가다가 그만 돌에 걸려 뒤집히고 말았어요.","「내 종이배가 다 젖었어!」 연이는 발을 동동 굴렀어요.","오빠가 빙그레 웃으며 말했어요. 「괜찮아. 이번엔 더 튼튼하게 같이 접어 보자.」","둘은 종이를 두 겹으로 겹쳐 새 종이배를 접었어요.","새 종이배는 돌 옆을 쓱 비켜 멀리멀리 떠내려갔어요. 연이는 손뼉을 치며 깡충깡충 뛰었어요."],"title":"연이의 종이배"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#11','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C6',2,'error','auto','기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?',ARRAY['K2-1-u8-X10','K2-1-u8-X19']::text[],false,'{"seq":11,"concept":"K2-1-u8-C6","difficulty":2,"kind":"error","stem":"기억에 남는 장면을 말했어요. 까닭을 빠뜨린 친구는 누구인가요?","options":[{"t":"건우 — 「나는 흥부네 박이 갈라지는 장면이 기억에 남아.」","correct":true,"mis_target":"K2-1-u8-X10"},{"t":"서아 — 「아이들이 춤추는 장면이 기억에 남아. 배고프던 아이들이 기뻐해서 나도 기뻤거든.」","mis":"K2-1-u8-X19"},{"t":"윤호 — 「박을 타며 노래하는 장면이 기억에 남아. 노랫소리가 신나서 따라 하고 싶었거든.」","mis":"K2-1-u8-X19"}],"explanation":["장면만 말하고 왜 기억에 남는지는 말하지 않았어요.","다른 두 친구는 까닭도 함께 말했어요.","「왜냐하면」을 붙여 한 번 더 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#12','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C7',2,'match','auto','인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"인형극에서 인물의 목소리와 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"눈물을 글썽이는 목소리","r":"고맙고 뭉클하다"},{"l":"작고 떨리는 목소리","r":"겁이 난다"},{"l":"크고 빠른 목소리","r":"신이 난다"}],"mis":"K2-1-u8-X12","explanation":["목소리의 크기와 빠르기에 마음이 묻어나요.","같은 말도 목소리에 따라 다르게 들려요.","그 목소리로 직접 말해 보며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#13','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C8',2,'mc','auto','줄거리를 읽고 답해 보세요. 「엄마가 고개에서 호랑이를 만났어요.」 바로 다음에 일어난 일은 무엇인가요?',ARRAY['K2-1-u8-X13']::text[],false,'{"seq":13,"concept":"K2-1-u8-C8","difficulty":2,"kind":"mc","stem":"줄거리를 읽고 답해 보세요. 「엄마가 고개에서 호랑이를 만났어요.」 바로 다음에 일어난 일은 무엇인가요?","options":[{"t":"호랑이가 엄마 옷을 입고 집으로 찾아갔어요","correct":true},{"t":"오누이가 해와 달이 되었어요","mis":"K2-1-u8-X13"},{"t":"엄마가 떡을 팔러 집을 나섰어요","mis":"K2-1-u8-X13"}],"explanation":["고개 다음에는 호랑이가 집으로 찾아갔어요.","다른 보기는 차례가 뒤섞였어요.","장소나 일이 바뀌는 곳에 줄을 그어 확인해요."],"asset":{"type":"passage","lines":["엄마는 오누이에게 문을 꼭 잠그라고 이르고 떡을 팔러 집을 나섰어요.","떡을 팔고 고개를 넘어오던 엄마는 호랑이를 만났어요.","호랑이는 엄마 옷을 입고 오누이가 기다리는 집으로 찾아갔어요.","오누이는 뒷문으로 빠져나가 우물가 나무 위로 올라갔어요.","하늘에서 내려온 튼튼한 동아줄을 잡은 오누이는 하늘로 올라가 해와 달이 되었어요."],"title":"해와 달이 된 오누이 — 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#14','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',2,'mc','auto','받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"받침이 넘어가는 소리를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"물이 → [무리]","correct":true},{"t":"물이 → [물이]","mis":"K2-1-u8-X18"},{"t":"물이 → [무이]","mis":"K2-1-u8-X18"}],"explanation":["받침 ㄹ이 뒤 글자로 넘어가 [무리]로 소리 나요.","다른 보기는 받침을 넘기지 않았거나 넘기지 않아야 할 곳에서 넘겼어요.","받침 뒤 글자가 「ㅇ」으로 시작하는지 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#15','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C10',2,'mc','auto','편지를 읽고 답해 보세요. 서윤이가 보보에게 덩달아 기뻤다고 한 때는 언제인가요?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":15,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"편지를 읽고 답해 보세요. 서윤이가 보보에게 덩달아 기뻤다고 한 때는 언제인가요?","options":[{"t":"토토와 다미가 음식을 나눠 줄 때","correct":true},{"t":"도시락이 텅 비어 있을 때","mis":"K2-1-u8-X14"},{"t":"보보가 나무 뒤에 혼자 앉았을 때","mis":"K2-1-u8-X14"}],"explanation":["친구들이 음식을 나눠 줄 때 덩달아 기뻤다고 했어요.","다른 보기는 편지의 다른 부분이에요.","누구에게 · 하고 싶은 말 · 왜 · 누가를 나눠 짚어요."],"asset":{"type":"passage","lines":["보보에게","보보야, 도시락이 텅 비어 있을 때 많이 속상했지?","토토와 다미가 음식을 나눠 줄 때 나도 덩달아 기뻤어.","다음 소풍에는 꼭 맛있는 도시락을 싸 가길 바라.","— 서윤이가"],"title":"서윤이가 보보에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#16','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C12',2,'error','auto','모둠이 인형극을 준비하는 모습이에요. 바르지 않게 준비한 친구는 누구인가요?',ARRAY['K2-1-u8-X16','K2-1-u8-X19']::text[],false,'{"seq":16,"concept":"K2-1-u8-C12","difficulty":2,"kind":"error","stem":"모둠이 인형극을 준비하는 모습이에요. 바르지 않게 준비한 친구는 누구인가요?","options":[{"t":"지안 — 인형 꾸미기에만 매달려 대사 연습을 하지 않았어요","correct":true,"mis_target":"K2-1-u8-X16"},{"t":"아린 — 맡은 인물의 마음을 생각하며 대사를 연습했어요","mis":"K2-1-u8-X19"},{"t":"준우 — 해설을 맡아 장면을 천천히 알려 주는 연습을 했어요","mis":"K2-1-u8-X19"}],"explanation":["인형 꾸미기보다 연습과 인형극 놀이가 더 중요해요.","다른 두 친구는 약속을 바르게 지켰어요.","물음의 「바르지 않게」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#17','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 대본을 읽고 답해 보세요. 아우가 눈물을 글썽이며 「형님, 고맙습니다.」라고 한 까닭은 무엇인가요?',ARRAY['K2-1-u8-X03','K2-1-u8-X05']::text[],false,'{"seq":17,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 대본을 읽고 답해 보세요. 아우가 눈물을 글썽이며 「형님, 고맙습니다.」라고 한 까닭은 무엇인가요?","options":[{"t":"형님도 자기를 위해 볏단을 옮겨 주었다는 것을 알게 되어서","correct":true},{"t":"볏단이 너무 무거워서","mis":"K2-1-u8-X03"},{"t":"형님에게 꾸중을 들어서","mis":"K2-1-u8-X05"}],"explanation":["서로를 위한 마음을 알고 뭉클했어요.","다른 보기는 대본에 없거나 인물의 마음과 맞지 않아요.","대본에서 인물의 말과 행동을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#18','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C2',3,'error','auto','글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?',ARRAY['K2-1-u8-X05','K2-1-u8-X19']::text[],false,'{"seq":18,"concept":"K2-1-u8-C2","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음과 그렇게 상상한 까닭을 말했어요. 잘못 상상한 친구는 누구인가요?","options":[{"t":"도담 — 「보물이 쏟아질 때 흥부는 실망했을 거야.」","correct":true,"mis_target":"K2-1-u8-X05"},{"t":"소율 — 「흥부는 꿈인가 싶었을 거야. 입을 다물지 못했으니까.」","mis":"K2-1-u8-X19"},{"t":"민준 — 「흥부와 아내는 설렜을 거야. 노래하며 박을 탔으니까.」","mis":"K2-1-u8-X19"}],"explanation":["입을 다물지 못할 만큼 놀란 흥부가 실망했을 리 없어요.","다른 두 친구는 말·행동·상황을 알맞게 들었어요.","「이 부분에 마음이 보이나?」 물어봐요."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#19','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C11',3,'ox','auto','감상을 발표할 때는 장면만 말하고 까닭은 말하지 않아도 돼요.',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":19,"concept":"K2-1-u8-C11","difficulty":3,"kind":"ox","stem":"감상을 발표할 때는 장면만 말하고 까닭은 말하지 않아도 돼요.","answer":"X","reason_options":[{"t":"까닭을 함께 말해야 내 생각과 느낌이 잘 전해지니까","correct":true},{"t":"까닭을 말하면 친구들이 지루해하니까","mis":"K2-1-u8-X15"}],"mis":"K2-1-u8-X15","explanation":["장면과 까닭을 함께 말해요.","나와 다른 감상도 존중하며 들어요.","친구 감상에서 좋은 점을 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#20','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',3,'ox','auto','「길이」는 글자 그대로 [길이]로 읽어야 자연스러워요.',ARRAY['K2-1-u8-X18']::text[],false,'{"seq":20,"concept":"K2-1-u8-C13","difficulty":3,"kind":"ox","stem":"「길이」는 글자 그대로 [길이]로 읽어야 자연스러워요.","answer":"X","reason_options":[{"t":"받침 ㄹ이 뒤로 넘어가 [기리]로 읽어야 자연스러우니까","correct":true},{"t":"받침이 넘어가면 다른 낱말이 되니까","mis":"K2-1-u8-X18"}],"mis":"K2-1-u8-X18","explanation":["「이」 앞에서 받침 ㄹ이 넘어가요.","받침은 뒤 글자가 「ㅇ」으로 시작할 때 넘어가요.","받침 뒤 글자를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#21','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C3',3,'mc','auto','시를 읽고 답해 보세요. 「몸짓 넣기」로 낭송할 때 알맞은 몸짓은 어느 것인가요?',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":21,"concept":"K2-1-u8-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 「몸짓 넣기」로 낭송할 때 알맞은 몸짓은 어느 것인가요?","options":[{"t":"「살금살금」에서 발끝으로 조용히 걷는 몸짓","correct":true},{"t":"「살금살금」에서 쿵쿵 뛰는 몸짓","mis":"K2-1-u8-X08"},{"t":"「새근새근」에서 크게 박수 치는 몸짓","mis":"K2-1-u8-X08"}],"explanation":["흉내 내는 말에 맞는 몸짓을 넣어요.","다른 보기는 시의 분위기와 맞지 않거나 낭송 방법을 헷갈렸어요.","시 분위기를 먼저 정하고 목소리를 골라요."],"asset":{"type":"passage","lines":["동생이 새근새근","잠이 들었다","나는 살금살금 다가가","이불을 살며시 덮어 준다","혹시 깰까 봐","숨도 조용조용 쉰다"],"title":"동생이 잠든 밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#22','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C12',3,'mc','auto','흥부네의 기쁜 마음을 살리는 인형극 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u8-X12','K2-1-u8-X16']::text[],false,'{"seq":22,"concept":"K2-1-u8-C12","difficulty":3,"kind":"mc","stem":"흥부네의 기쁜 마음을 살리는 인형극 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쌀이 쏟아질 때 흥부는 놀란 큰 목소리, 아이들 인형은 깡충깡충 뛰게 움직이기","correct":true},{"t":"모두 작은 목소리로 천천히 말하고 인형은 가만히 두기","mis":"K2-1-u8-X12"},{"t":"인형 꾸미기에 시간을 다 쓰고 대사는 공연 때 처음 읽기","mis":"K2-1-u8-X16"}],"explanation":["목소리와 움직임이 함께 기쁜 마음을 살려요.","다른 보기는 인형극을 준비하거나 공연하는 바른 방법이 아니에요.","「인형보다 놀이!」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#23','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C6',4,'essay','teacher','「흥부와 놀부」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"essay","stem":"「흥부와 놀부」 가운데 가장 기억에 남는 장면을 하나 골라 쓰고, 그 장면이 기억에 남는 까닭과 비슷한 내 경험을 써 보세요.","answer_guide":{"answer":"예: 아이들이 얼싸안고 덩실덩실 춤추는 장면이 가장 기억에 남아요. 늘 배고프던 아이들이 기뻐하는 모습에 저도 웃음이 났기 때문이에요. 저도 기다리던 선물을 받았을 때 동생과 껴안고 뛰었던 적이 있어요.","scoring_points":["기억에 남는 장면을 골라 썼는가","그 장면이 기억에 남는 까닭을 썼는가","비슷한 내 경험을 썼는가"]},"explanation":["기억에 남는 장면.","까닭.","비슷한 내 경험."],"asset":{"type":"passage","lines":["가을이 되자 흥부네 지붕 위에 커다란 박이 주렁주렁 열렸어요.","「슬근슬근 톱질하세!」 흥부와 아내는 노래를 부르며 박을 탔어요.","박이 쩍 갈라지자 하얀 쌀과 반짝이는 보물이 쏟아져 나왔어요.","흥부는 눈이 휘둥그레져 입을 다물지 못했어요.","배고프던 아이들은 서로 얼싸안고 덩실덩실 춤을 추었어요."],"title":"흥부와 놀부 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#24','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C7',4,'essay','teacher','인형극 대본을 읽고 답해 보세요. 아우의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"인형극 대본을 읽고 답해 보세요. 아우의 마음을 짐작해 쓰고, 그렇게 짐작한 까닭을 그 인물의 말·행동·목소리를 들어 써 보세요.","answer_guide":{"answer":"예: 아우는 놀랍고 고마웠을 거예요. 형을 보고 눈이 동그래졌고, 눈물을 글썽이며 「형님, 고맙습니다.」라고 말했기 때문이에요.","scoring_points":["인물의 마음을 썼는가","말·행동·목소리 가운데 근거를 들었는가","근거와 마음이 서로 맞는가"]},"explanation":["인물의 마음.","말·행동·목소리 근거.","근거와 마음이 맞는지."],"asset":{"type":"speech","turns":[{"who":"해설","text":"사흘째 밤, 하늘에 둥근 달이 떴어요."},{"who":"형","text":"(볏단을 지고 가다가 멈칫하며) 아니, 저기 오는 사람은……?"},{"who":"아우","text":"(눈이 동그래져) 형님! 형님도 볏단을 옮기고 계셨군요!"},{"who":"형","text":"(볏단을 내려놓고 아우를 꼭 안으며) 그랬구나. 네가 나를 생각해 주었구나."},{"who":"아우","text":"(눈물을 글썽이며) 형님, 고맙습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#25','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C10',4,'essay','teacher','「콩쥐팥쥐」의 두꺼비에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「콩쥐팥쥐」의 두꺼비에게 편지를 써 보세요. 받는 인물·하고 싶은 말·그 까닭·쓴 사람이 드러나게 써 보세요.","answer_guide":{"answer":"예: 두꺼비에게 — 두꺼비야, 울고 있던 콩쥐를 위해 독 구멍을 막아 줘서 고마워. 네 덕분에 콩쥐가 웃을 수 있었어. 나도 어려운 친구를 도와줄게. — 민지가","scoring_points":["받는 인물과 쓴 사람을 밝혔는가","인물에게 하고 싶은 말을 썼는가","하고 싶은 말의 까닭을 작품과 이어 썼는가"]},"explanation":["받는 인물·쓴 사람.","하고 싶은 말.","작품과 이은 까닭."],"asset":{"type":"passage","lines":["새어머니는 콩쥐에게 밑 빠진 독에 물을 가득 채워 놓으라고 했어요.","콩쥐가 아무리 물을 길어 부어도 물은 줄줄 새어 나갔어요.","콩쥐는 독 앞에 털썩 주저앉아 훌쩍훌쩍 울었어요.","그때 커다란 두꺼비가 엉금엉금 나타나 말했어요. 「내가 구멍을 막아 줄게.」","두꺼비가 독 밑 구멍을 막자 물이 찰랑찰랑 차올랐어요.","콩쥐는 두꺼비를 꼭 끌어안으며 말했어요. 「고마워, 두꺼비야.」"],"title":"콩쥐팥쥐 — 한 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
